348	/****************************************************************************
349	 * Name: jd9853_init
350	 *
351	 * Description:
352	 *   Send jd9853 internal init commands.
353	 *
354	 * Assumption/Limitations:
355	 *   Initialization is hardware-specific and may need to be rewritten for
356	 *   different modules.
357	 *
358	 ****************************************************************************/
359	
360	static void jd9853_init(FAR struct jd9853_dev_s *dev)
361	{
362	  /* Unlock chip registers */
363	
364	  jd9853_cmddata(dev, JD9853_PASSWORD, (const uint8_t *)"\x98\x53", 2);
365	
366	  /* Power settings (reference sequence for the 2.01" TFT=201 panel) */
367	
368	  jd9853_cmddata(dev, JD9853_SET_DCDC, (const uint8_t *)"\x23", 1);
369	  jd9853_cmddata(dev, JD9853_GAMMA_SET_CMD, (const uint8_t *)
370	                 "\x00\x47\x00\x6F", 4);
371	  jd9853_cmddata(dev, JD9853_POWER_CTRL, (const uint8_t *)
372	                 "\x1C\x1A\x55\x73\x63\xF0", 6);
373	
374	  /* Timing configuration */
375	
376	  jd9853_cmddata(dev, JD9853_SETSTBA, (const uint8_t *)"\x44\x44", 2);
377	  jd9853_cmddata(dev, JD9853_SETPANEL, (const uint8_t *)"\x12", 1);
378	  jd9853_cmddata(dev, JD9853_SETRGBCYC, (const uint8_t *)
379	                 "\x7D\x07\x14\x06\xCF\x71\x72\x77", 8);
380	  jd9853_cmddata(dev, JD9853_SETTCON, (const uint8_t *)
381	                 "\x00\x00\xA0\x79\x0B\x0A\x16\x79\x0B\x0A\x16\x82", 12);
382	
383	  /* Gamma correction (reference G2.2 table for the 2.01" panel) */
384	
385	  jd9853_cmddata(dev, JD9853_R_GAMMA_SET_CMD, (const uint8_t *)
386	                 "\x3F\x32\x29\x29\x27\x2B\x27\x28\x28\x26\x25\x17\x12\x0d\
387	                  \x04\x00\x3F\x32\x29\x29\x27\x2B\x27\x28\x28\x26\x25\x17\
388	                  \x12\x0d\x04\x00", 32);
389	
390	  /* Power management */
391	
392	  jd9853_cmddata(dev, JD9853_SETGD, (const uint8_t *)
393	                 "\x04\x06\x6B\x0F\x00", 5);
394	  jd9853_cmddata(dev, JD9853_RAM_CTRL, (const uint8_t *)"\x00\x30", 2);
395	  jd9853_cmddata(dev, JD9853_SETOSCM, (const uint8_t *)"\x14", 1);
396	
397	  /* Page 1 settings */
398	
399	  jd9853_cmddata(dev, JD9853_SET_PAGE_CMD, (const uint8_t *)"\x01", 1);
400	  jd9853_cmddata(dev, JD9853_SETPANEL_1, (const uint8_t *)
401	                 "\x03\x13\xEF\x35\x35", 5);
402	  jd9853_cmddata(dev, JD9853_SETTCON_1, (const uint8_t *)
403	                 "\x14\x15\xC0", 3);
404	  jd9853_cmddata(dev, JD9853_SETTCON_2, (const uint8_t *)
405	                 "\x06\x3A", 2);
406	  jd9853_cmddata(dev, JD9853_SETTCON_3, (const uint8_t *)"\x72\x12", 2);
407	  jd9853_cmddata(dev, JD9853_SETDISP_1, (const uint8_t *)"\x00", 1);
408	
409	  /* Page 2: interface settings */
410	
411	  jd9853_cmddata(dev, JD9853_SET_PAGE_CMD, (const uint8_t *)"\x02", 1);
412	  jd9853_cmddata(dev, 0xE5, (const uint8_t *)"\x00\x02\x00", 3);
413	  jd9853_cmddata(dev, 0xE5, (const uint8_t *)"\x01\x02\x00", 3);
414	
415	  /* Back to page 0 */
416	
417	  jd9853_cmddata(dev, JD9853_SET_PAGE_CMD, (const uint8_t *)"\x00", 1);
418	
419	  jd9853_cmddata(dev, JD9853_TEON, (const uint8_t *)"\x00", 1);
420	
421	  jd9853_sendcmd(dev, JD9853_SLEEP_OUT);
422	  up_mdelay(120);
423	
424	  /* Page 2 again after sleep out, then back to page 0 */
425	
426	  jd9853_cmddata(dev, JD9853_SET_PAGE_CMD, (const uint8_t *)"\x02", 1);
427	  jd9853_cmddata(dev, 0xE5, (const uint8_t *)"\x00\x02\x00", 3);
428	  jd9853_cmddata(dev, JD9853_SET_PAGE_CMD, (const uint8_t *)"\x00", 1);
429	}
