377	  /* Enable the SPI1 clock gate and pin the source clock to XTAL 26M. */
378	
379	  regval  = getreg32(BK7258_SYS_DEV_CLK_EN);
380	  regval |= BK7258_SYS_SPI1_CLK_EN;
381	  putreg32(regval, BK7258_SYS_DEV_CLK_EN);
382	
383	  regval  = getreg32(BK7258_SYS_CLKSEL);
384	  regval &= ~BK7258_SYS_SPI1_APLL;
385	  putreg32(regval, BK7258_SYS_CLKSEL);
386	
387	  /* Route SCK (GPIO2) and MOSI (GPIO4) to the SPI1 controller.  CS
388	   * (GPIO3) and D/C (GPIO5) stay plain GPIO outputs.
389	   */
390	
391	  bk7258_gpio_periph(BOARD_LCD_SCL_PIN, BK7258_SPI1_FUNC_SCK);
392	  bk7258_gpio_periph(BOARD_LCD_SDA_PIN, BK7258_SPI1_FUNC_MOSI);
393	  bk7258_gpio_config_output(BOARD_LCD_CS_PIN, false);
394	  bk7258_gpio_config_output(BOARD_LCD_DC_PIN, false);
395	
396	  /* Idle levels: CS de-asserted high, D/C low until a transfer begins. */
397	
398	  bk7258_gpio_write(BOARD_LCD_CS_PIN, true);
399	  bk7258_gpio_write(BOARD_LCD_DC_PIN, false);
400	
401	  /* Bring the controller out of reset.  soft_reset is a low-active reset
402	   * bit: the ARMINO spi_ll_init() sets it to 1 and keeps it there (the
403	   * controller is out of reset while it is 1).  The earlier draft cleared
404	   * it back to 0, which held the shift engine in reset: registers stayed
405	   * writable through AHB but SCK never ran and tx_finish_int never fired.
406	   */
407	
408	  hw->global_ctrl.soft_reset = 1;
409	
410	  hw->ctrl.v = 0;
411	  hw->cfg.v  = 0;
412	  hw->int_status.v = 0xffff;  /* clear sticky status */
413	
414	  /* Mirror the ARMINO spi_hal_configure() interrupt enables. */
415	
416	  hw->ctrl.tx_udf_int_en = 1;
417	  hw->ctrl.rx_ovf_int_en = 1;
418	  hw->ctrl.tx_fifo_int_en = 0;
419	  hw->ctrl.rx_fifo_int_en = 1;
420	
421	  hw->ctrl.master_en    = 1;  /* master role */
422	  hw->ctrl.bit_width    = 0;  /* 8-bit */
423	  hw->ctrl.lsb_first_en = 0;  /* MSB first */
424	  hw->ctrl.wire3_en     = 0;  /* 4-wire (MOSI/MISO) */
425	  hw->ctrl.cpol         = 0;  /* mode 0 */
426	  hw->ctrl.cpha         = 0;
427	  hw->ctrl.enable       = 1;
428	
429	  hw->cfg.tx_finish_int_en = 1;
430	  hw->cfg.rx_finish_int_en = 1;
431	
432	  hw->int_status.tx_fifo_int = 1;        /* write-1-clear */
433	  hw->int_status.rx_fifo_int = 1;        /* write-1-clear */
434	
435	  priv->hw       = hw;
436	  priv->frequency = 0;
437	  priv->actual    = 0;
438	  priv->mode      = SPIDEV_MODE0;
439	  priv->nbits     = 8;
440	  priv->dev.ops   = &g_bk7258_spiops;
441	  nxmutex_init(&priv->lock);
442	
443	  return &priv->dev;
444	}
