174	static uint32_t bk7258_spi_setfrequency(FAR struct spi_dev_s *dev,
175	                                        uint32_t frequency)
176	{
177	  FAR struct bk7258_spi_dev_s *priv = (FAR struct bk7258_spi_dev_s *)dev;
178	  uint32_t clk_rate;
179	
180	  if (frequency > BK7258_SPI1_MAX_BAUD)
181	    {
182	      frequency = BK7258_SPI1_MAX_BAUD;
183	    }
184	
185	  /* baud = f_src / (2 * clk_rate), round up to stay below the request */
186	
187	  clk_rate = (BK7258_SPI1_SRC_CLK + (2 * frequency) - 1) / (2 * frequency);
188	  if (clk_rate < 1)
189	    {
190	      clk_rate = 1;
191	    }
192	  else if (clk_rate > 0xff)
193	    {
194	      clk_rate = 0xff;
195	    }
196	
197	  priv->hw->ctrl.clk_rate = clk_rate;
198	
199	  priv->frequency = frequency;
200	  priv->actual    = BK7258_SPI1_SRC_CLK / (2 * clk_rate);
201	
202	  return priv->actual;
203	}
