538	bk_err_t bk_spi_init(spi_id_t id, const spi_config_t *config)
539	{
540		BK_RETURN_ON_NULL(config);
541		SPI_RETURN_ON_NOT_INIT();
542		SPI_RETURN_ON_INVALID_ID(id);
543		SPI_CHECK_SECURE(id);
544	
545	#if (CONFIG_SPI_PM_CB_SUPPORT)
546		pm_cb_conf_t enter_config = {bk_spi_backup, (void *)id};
547		if (id == SPI_ID_1) {
548			bk_pm_module_lv_sleep_state_clear(PM_DEV_ID_SPI_2);
549			bk_pm_module_vote_power_ctrl(PM_POWER_SUB_MODULE_NAME_BAKP_SPI1, PM_POWER_MODULE_STATE_ON);
550			bk_pm_sleep_register_cb(PM_MODE_LOW_VOLTAGE, PM_DEV_ID_SPI_2, &enter_config, NULL);
551		}
552	#endif
553		spi_id_init_common(id);
554		spi_hal_init(&s_spi[id].hal);
555		spi_hal_configure(&s_spi[id].hal, config);
556		spi_hal_start_common(&s_spi[id].hal);
557	#if (CONFIG_SPI_DMA)
558		if (config->dma_mode) {
559	#if (!CONFIG_SYSTEM_CTRL)
560			gpio_spi_sel(GPIO_SPI_MAP_MODE0);
561	#endif
562			spi_dma_tx_init(id, config->spi_tx_dma_chan, config->spi_tx_dma_width);
563			spi_dma_rx_init(id, config->spi_rx_dma_chan, config->spi_rx_dma_width);
564		}
565	#endif
566	
567		return BK_OK;
568	}
