978	bk_err_t bk_spi_dma_write_bytes(spi_id_t id, const void *data, uint32_t size)
979	{
980		BK_RETURN_ON_NULL(data);
981		SPI_RETURN_ON_INVALID_ID(id);
982		SPI_RETURN_ON_ID_NOT_INIT(id);
983	
984		int32_t left_len = size;
985		uint32_t tx_len = 0;
986		uint32_t buf_offset = 0;
987		while(left_len > 0) {
988			tx_len = (left_len < SPI_MAX_LENGTH)? left_len : SPI_MAX_LENGTH;
989			SPI_LOGV("tx_len = 0x%x, left_len=0x%x\r\n", tx_len, left_len);
990	
991			uint32_t int_level = spi_enter_critical();
992			s_spi[id].is_tx_blocked = true;
993			s_current_spi_dma_wr_id = id;
994			spi_hal_clear_tx_fifo(&s_spi[id].hal);
995			//set spi trans_len as 0, to increase max trans_len from 4096(spi max length) to 65536(dma max length).
996			spi_hal_set_tx_trans_len(&s_spi[id].hal, 0);
997			spi_hal_enable_tx(&s_spi[id].hal);
998			spi_exit_critical(int_level);
999			bk_dma_write(s_spi[id].spi_tx_dma_chan, (uint8_t *)data + buf_offset, tx_len);
1000			rtos_get_semaphore(&s_spi[id].tx_sema, BEKEN_NEVER_TIMEOUT);
1001			int_level = spi_enter_critical();
1002			//wait spi last fifo data transfer finish
1003			spi_hal_enable_tx_fifo_int(&s_spi[id].hal);
1004			for (int i = 0; i <= 500; i++) {
1005				bk_delay_us(1);
1006				SPI_LOGV("index = %d, id=%d, tx_fifo_int_status = %d\n", i, id, spi_hal_is_tx_fifo_int_triggered(&s_spi[id].hal));
1007				if(spi_hal_is_tx_fifo_int_triggered(&s_spi[id].hal)) {
1008					bk_delay_us(1);
1009					break;
1010				}
1011				if(i == 500)
1012					SPI_LOGE("wait tx fifo empty timeout.\n");
1013			}
1014			spi_hal_disable_tx_fifo_int(&s_spi[id].hal);
1015			spi_hal_clear_tx_fifo_int_status(&s_spi[id].hal);
1016			spi_hal_disable_tx(&s_spi[id].hal);
1017			bk_dma_stop(s_spi[id].spi_tx_dma_chan);
1018			spi_exit_critical(int_level);
1019			left_len -= tx_len;
1020			buf_offset += tx_len;
1021		}
1022	
1023		return BK_OK;
1024	}
