static int binary_search(const uint32_t *array, uint32_t size, uint32_t target)
{
	uint32_t left = 0;
	uint32_t right = size - 1;
	uint32_t mid = (left + right) / 2;

	while (left <= right && mid < size) {
		mid = (left + right) / 2;
		if (array[mid] == target) {
			return mid;
		}
		if (target > array[mid]) {
			right = mid - 1;
		} else {
			left = mid + 1;
		}
	}
	return BK_FAIL;
}
#endif

