188	bk_err_t bk_pm_module_vote_power_ctrl(pm_power_module_name_e module,
189	                                       pm_power_module_state_e power_state)
190	{
191	  bool enable;
192	
193	  if (power_state == PM_POWER_MODULE_STATE_ON)
194	    {
195	      enable = true;
196	    }
197	  else if (power_state == PM_POWER_MODULE_STATE_OFF)
198	    {
199	      enable = false;
200	    }
201	  else
202	    {
203	      return BK_ERR_PARAM;
204	    }
205	
206	  if (module == PM_POWER_MODULE_NAME_WIFIP_MAC)
207	    {
208	      return bk7258_mac_power(enable) == OK ? BK_OK : BK_FAIL;
209	    }
210	  else if ((uint32_t)module >=
211	             (uint32_t)PM_POWER_MODULE_NAME_BAKP *
212	             PM_MODULE_SUB_POWER_DOMAIN_MAX &&
213	           (uint32_t)module <=
214	             (uint32_t)PM_POWER_MODULE_NAME_BAKP *
215	             PM_MODULE_SUB_POWER_DOMAIN_MAX + 16)
216	    {
217	      /* Armino pm.c:504-536 and :726-755: BAKP submodules hold their
218	       * parent domain until the final user releases it.  This is required
219	       * by the BK7258 authority SARADC PM callback path. */
220	      const uint32_t bit = UINT32_C(1) <<
221	        ((uint32_t)module %
222	         ((uint32_t)PM_POWER_MODULE_NAME_BAKP *
223	          PM_MODULE_SUB_POWER_DOMAIN_MAX));
224	      irqstate_t flags = spin_lock_irqsave(&g_bakp_power_lock);
225	
226	      if (enable)
227	        {
228	          g_bakp_submodule_state |= bit;
229	          spin_unlock_irqrestore(&g_bakp_power_lock, flags);
230	
231	          if (sys_drv_module_power_state_get(PM_POWER_MODULE_NAME_BAKP) == 0x0)
232	            {
233	              return BK_OK;
234	            }
235	
236	          return bk7258_bakp_power(true) == OK ? BK_OK : BK_FAIL;
237	        }
238	
239	      g_bakp_submodule_state &= ~bit;
240	      if (g_bakp_submodule_state == 0)
241	        {
242	          spin_unlock_irqrestore(&g_bakp_power_lock, flags);
243	          return bk7258_bakp_power(false) == OK ? BK_OK : BK_FAIL;
244	        }
245	
246	      spin_unlock_irqrestore(&g_bakp_power_lock, flags);
247	      return BK_OK;
248	    }
