  if (power_up)
    {
      v |= (UINT32_C(1) << (dev - offset));
    }
  else
    {
      v &= ~(UINT32_C(1) << (dev - offset));
    }

  if (dev >= HP_CLK_PWR_ID_H264)
    {
      sys_ll_set_reserver_reg0xd_value(v);
    }
