static void jd9853_setorientation(FAR struct jd9853_dev_s *dev)
{
  uint8_t reg = 0x00;

#if !defined(CONFIG_LCD_PORTRAIT) || defined(CONFIG_LCD_JD9853_BGR)

#  if defined(CONFIG_LCD_RLANDSCAPE)

  reg = JD9853_MADCTL_MY | JD9853_MADCTL_MV;

