142	  int phase = v % 25;
143	  int amp = (phase < 13) ? (phase * 5 / 12) : ((25 - phase) * 5 / 12);
144	  int sign = (seg % 2 == 0) ? 1 : -1;
145	  lv_obj_set_style_translate_x(o, sign * amp, 0);
146	}
