148	static void stop_anim(void)
149	{
150	  /* Delete any anim bound to our widgets. lv_anim_delete is a no-op if none. */
151	  if (s_pet.ring)   lv_anim_delete(s_pet.ring,   spin_cb);
152	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, breathe_cb);
153	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, shake_cb);
154	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, blink_cb);
155	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, float_cb);
156	  s_pet.anim_active = false;
157	}
158	
159	/* Per-state face: each agent state shows a distinct expression (eyes-only edits
160	 * on the CC0 base face — see gen_pet_expressions.py).  WAITING returns the
161	 * open-eye base because its blink anim swaps base↔blink itself. */
162	static const lv_image_dsc_t *sprite_for(enum pet_state st)
163	{
164	  switch (st)
165	    {
166	      case PET_STATE_LISTENING: return &pet_sprite_eyes_down;
167	      case PET_STATE_THINKING:  return &pet_sprite_eyes_up;
168	      case PET_STATE_EXECUTING: return &pet_sprite_focused;
169	      case PET_STATE_ERROR:     return &pet_sprite_error;
170	      case PET_STATE_WAITING:
171	      case PET_STATE_IDLE:
172	      default:                  return &pet_sprite_base;
173	    }
174	}
175	
176	static void start_anim_for(enum pet_state st)
177	{
178	  lv_anim_t a;
179	  uint32_t color = s_state_color[st];
180	
181	  stop_anim();
182	  if (!s_pet.ring || !s_pet.sprite) return;
183	
184	  /* Indicator color always tracks state (the dark track stays constant);
185	   * base angles reset per effect. */
186	  lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(color), LV_PART_INDICATOR);
187	
188	  /* Face tracks state too — each state's expression frame (blink anim swaps it). */
189	  lv_image_set_src(s_pet.sprite, sprite_for(st));
190	
191	  switch (st)
192	    {
193	      case PET_STATE_THINKING:
194	      case PET_STATE_LISTENING:
195	        lv_anim_init(&a);
196	        lv_anim_set_var(&a, s_pet.ring);
197	        lv_anim_set_values(&a, 0, 360);
198	        lv_anim_set_time(&a, 1400);
199	        lv_anim_set_exec_cb(&a, spin_cb);
200	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
201	        lv_anim_start(&a);
202	        break;
203	      case PET_STATE_EXECUTING:
204	        lv_anim_init(&a);
205	        lv_anim_set_var(&a, s_pet.ring);
206	        lv_anim_set_values(&a, 0, 360);
207	        lv_anim_set_time(&a, 900);
208	        lv_anim_set_exec_cb(&a, fill_cb);
209	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
210	        lv_anim_start(&a);
211	        break;
212	      case PET_STATE_IDLE:
213	        lv_anim_init(&a);
214	        lv_anim_set_var(&a, s_pet.sprite);
215	        lv_anim_set_values(&a, 0, 100);
216	        lv_anim_set_time(&a, 1800);
217	        lv_anim_set_exec_cb(&a, breathe_cb);
218	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
219	        lv_anim_start(&a);
220	        /* Layered float: a slow bob on a distinct period so the two effects
221	         * don't phase-lock.  lv_anim_start copies `a`, so it is safe to reuse
222	         * the same local descriptor for a second anim. */
223	        lv_anim_init(&a);
224	        lv_anim_set_var(&a, s_pet.sprite);
225	        lv_anim_set_values(&a, 0, 100);
226	        lv_anim_set_time(&a, 2600);
227	        lv_anim_set_exec_cb(&a, float_cb);
228	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
229	        lv_anim_start(&a);
230	        lv_arc_set_angles(s_pet.ring, 0, 360);  /* full ring */
231	        break;
232	      case PET_STATE_WAITING:
233	        lv_anim_init(&a);
234	        lv_anim_set_var(&a, s_pet.sprite);
235	        lv_anim_set_values(&a, 0, 100);
236	        lv_anim_set_time(&a, 900);
237	        lv_anim_set_exec_cb(&a, blink_cb);
238	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
239	        lv_anim_start(&a);
240	        lv_arc_set_angles(s_pet.ring, 0, 360);
241	        break;
242	      case PET_STATE_ERROR:
243	        lv_anim_init(&a);
244	        lv_anim_set_var(&a, s_pet.sprite);
245	        lv_anim_set_values(&a, 0, 100);
246	        lv_anim_set_time(&a, 350);
247	        lv_anim_set_exec_cb(&a, shake_cb);
248	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
249	        lv_anim_start(&a);
250	        lv_arc_set_angles(s_pet.ring, 0, 360);
251	        break;
252	      default:
253	        lv_arc_set_angles(s_pet.ring, 0, 360);
254	        break;
255	    }
256	  s_pet.anim_active = true;
257	}
