259	/* ---------- async apply (runs in LVGL thread) ---------- */
260	
261	static void apply_state_async_cb(void *data)
262	{
263	  enum pet_state st = (enum pet_state)(intptr_t)data;
264	  if (!s_pet.initialized || !s_pet.sprite) return;
265	
266	  s_pet.state = st;
267	
268	  /* Reset the sprite to a clean base frame; per-state anim re-derives it. */
269	  lv_image_set_src(s_pet.sprite, &pet_sprite_base);
270	  lv_obj_set_style_translate_x(s_pet.sprite, 0, 0);  /* clear any shake offset */
271	  lv_obj_set_style_translate_y(s_pet.sprite, 0, 0);  /* clear any float offset */
272	  lv_obj_set_style_opa(s_pet.sprite, LV_OPA_COVER, 0);
273	
274	  if (s_pet.label) lv_label_set_text(s_pet.label, s_state_text[st]);
275	  if (s_pet.status_dot) {
276	    lv_obj_set_style_bg_color(s_pet.status_dot, lv_color_hex(s_state_color[st]), 0);
277	  }
278	
279	  start_anim_for(st);
280	  syslog(LOG_INFO, "[%s] state → %s\n", TAG, s_state_text[st]);
281	}
