283	void pet_status_view_set_state(enum pet_state state)
284	{
285	  if ((int)state < 0 || (int)state > PET_STATE_ERROR) return;
286	  /* Async: widget mutation must happen in the LVGL thread. */
287	  lv_async_call(apply_state_async_cb, (void *)(intptr_t)state);
288	}
