290	/* ---------- screen show / hide ---------- */
291	
292	static void show_async_cb(void *data)
293	{
294	  (void)data;
295	  if (!s_pet.initialized || !s_pet.screen || s_pet.visible) return;
296	  s_pet.prev_screen = lv_screen_active();
297	  lv_screen_load(s_pet.screen);
298	  /* Force a synchronous refresh so the first frame flushes to the framebuffer.
299	   * qemu goldfish headless skips the first async frame of a screen switched in
300	   * after lvgl init — the same lazy-flush issue particle_flow_view works around
301	   * with an explicit invalidate + lv_refr_now.  (Boot-time only; post-boot
302	   * switches on qemu still won't flush, but real CP /dev/lcd0 is screen-agnostic.) */
303	  lv_obj_set_style_bg_color(s_pet.screen, lv_color_hex(UI_PAL_BG), 0);
304	  lv_obj_set_style_bg_opa(s_pet.screen, LV_OPA_COVER, 0);
305	  lv_obj_invalidate(s_pet.screen);
306	  lv_refr_now(lv_display_get_default());
307	  s_pet.visible = true;
308	  /* Re-assert current state's animation (lv_anim may have been paused off-screen). */
309	  start_anim_for(s_pet.state);
310	  syslog(LOG_INFO, "[%s] pet screen shown\n", TAG);
311	}
312	
313	void pet_status_view_show(void)
314	{
315	  if (!s_pet.initialized) return;
316	  lv_async_call(show_async_cb, NULL);
317	}
