319	static void hide_async_cb(void *data)
320	{
321	  (void)data;
322	  if (!s_pet.initialized || !s_pet.visible) return;
323	  stop_anim();
324	  if (s_pet.prev_screen) lv_screen_load(s_pet.prev_screen);
325	  s_pet.visible = false;
326	  syslog(LOG_INFO, "[%s] pet screen hidden\n", TAG);
327	}
