341	
342	int pet_status_view_init(void)
343	{
344	  if (s_pet.initialized) return 0;
345	
346	  memset(&s_pet, 0, sizeof(s_pet));
347	  s_pet.state = PET_STATE_IDLE;
348	
349	  s_pet.screen = lv_obj_create(NULL);
350	  if (!s_pet.screen) return -ENOMEM;
351	  lv_obj_set_style_bg_color(s_pet.screen, lv_color_hex(UI_PAL_BG), 0);
352	  lv_obj_set_style_bg_opa(s_pet.screen, LV_OPA_COVER, 0);
353	  lv_obj_set_style_text_font(s_pet.screen, &lv_font_misans_16_cjk, 0);
354	
355	  /* Ring (arc) — centered, subtle dark track, state-colored indicator. */
356	  s_pet.ring = lv_arc_create(s_pet.screen);
357	  if (s_pet.ring)
358	    {
359	      lv_obj_set_size(s_pet.ring, PET_RING_SIZE, PET_RING_SIZE);
360	      lv_obj_center(s_pet.ring);
361	      lv_arc_set_rotation(s_pet.ring, 0);
362	      lv_arc_set_bg_angles(s_pet.ring, 0, 360);
363	      lv_arc_set_angles(s_pet.ring, 0, 360);
364	      lv_arc_set_range(s_pet.ring, 0, 360);
365	      /* Track (LV_PART_MAIN): a subtle dark full circle that stays put. */
366	      lv_obj_set_style_arc_width(s_pet.ring, 4, LV_PART_MAIN);
367	      lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(0x232628), LV_PART_MAIN);
368	      lv_obj_set_style_arc_rounded(s_pet.ring, true, LV_PART_MAIN);
369	      /* Indicator (LV_PART_INDICATOR): the state-colored spinner / fill.
370	       * (Previously only LV_PART_MAIN was styled, so the animated segment fell
371	       * back to the theme's default blue arc — the "ugly" ring.) */
372	      lv_obj_set_style_arc_width(s_pet.ring, 4, LV_PART_INDICATOR);
373	      lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(UI_PAL_IDLE), LV_PART_INDICATOR);
374	      lv_obj_set_style_arc_rounded(s_pet.ring, true, LV_PART_INDICATOR);
375	      lv_obj_remove_flag(s_pet.ring, LV_OBJ_FLAG_CLICKABLE);
376	      /* Hide the arc knob. */
377	      lv_obj_set_style_bg_opa(s_pet.ring, LV_OPA_TRANSP, LV_PART_KNOB);
378	    }
379	
380	  /* Pixel pet — CC0 sprite scaled 6x (nearest-neighbor for crisp pixels). */
381	  s_pet.sprite = lv_image_create(s_pet.screen);
382	  if (!s_pet.sprite) goto fail;
383	  lv_image_set_src(s_pet.sprite, &pet_sprite_base);
384	  lv_image_set_antialias(s_pet.sprite, false);
385	  lv_image_set_scale(s_pet.sprite, PET_SPRITE_SCALE * 256);
386	  lv_obj_center(s_pet.sprite);
387	
388	  /* Status caption row below the sprite: a colored status dot (HachimoDock
389	   * circular status marker) + the state text, laid out horizontally. */
390	  {
391	    lv_obj_t *caption = lv_obj_create(s_pet.screen);
392	    if (!caption) goto fail;
393	    lv_obj_remove_flag(caption, LV_OBJ_FLAG_SCROLLABLE);
394	    lv_obj_set_size(caption, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
395	    lv_obj_set_style_bg_opa(caption, LV_OPA_TRANSP, 0);
396	    lv_obj_set_style_border_width(caption, 0, 0);
397	    lv_obj_set_style_pad_all(caption, 0, 0);
398	    lv_obj_set_flex_flow(caption, LV_FLEX_FLOW_ROW);
399	    lv_obj_set_flex_align(caption, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER,
400	                          LV_FLEX_ALIGN_CENTER);
401	    lv_obj_set_style_pad_column(caption, 6, 0);
402	    lv_obj_align(caption, LV_ALIGN_CENTER, 0, PET_LABEL_DY);
403	
404	    s_pet.status_dot = lv_obj_create(caption);
405	    if (s_pet.status_dot)
406	      {
407	        lv_obj_remove_flag(s_pet.status_dot, LV_OBJ_FLAG_SCROLLABLE);
408	        lv_obj_set_size(s_pet.status_dot, 8, 8);
409	        lv_obj_set_style_radius(s_pet.status_dot, LV_RADIUS_CIRCLE, 0);
410	        lv_obj_set_style_bg_color(s_pet.status_dot, lv_color_hex(UI_PAL_IDLE), 0);
411	        lv_obj_set_style_bg_opa(s_pet.status_dot, LV_OPA_COVER, 0);
412	        lv_obj_set_style_border_width(s_pet.status_dot, 0, 0);
413	        lv_obj_set_style_pad_all(s_pet.status_dot, 0, 0);
414	      }
415	
416	    s_pet.label = lv_label_create(caption);
417	    if (s_pet.label)
418	      {
419	        lv_label_set_text(s_pet.label, s_state_text[PET_STATE_IDLE]);
420	        lv_obj_set_style_text_color(s_pet.label, lv_color_hex(0xC9CECC), 0);
421	        lv_obj_set_style_text_font(s_pet.label, &lv_font_misans_16_cjk, 0);
422	      }
423	  }
424	
425	  s_pet.initialized = true;
426	  syslog(LOG_INFO, "[%s] init OK (像素宠物状态环)\n", TAG);
427	  return 0;
428	
429	fail:
430	  if (s_pet.screen) lv_obj_del(s_pet.screen);
431	  memset(&s_pet, 0, sizeof(s_pet));
432	  return -ENOMEM;
433	}
