50	#define N_PARTICLES    18
51	#define PARTICLE_DIAM  7        /* px, odd so center pixel is exact */
52	#define CORE_DIAM      34
53	#define GUIDE_RING_DIAM 150
54	#define VEL_Q           8        /* velocity fixed-point: 256 = 1 px/tick */
55	#define ONE_PX          (1 << VEL_Q)
56	#define TICK_MS         33
57	
58	/* State palette — HachimoDock 柔和低饱和状态色，语义同 pet_status_view。 */
59	static const uint32_t s_state_color[] = {
60	  UI_PAL_IDLE, UI_PAL_LISTEN, UI_PAL_THINK, UI_PAL_EXEC, UI_PAL_WAIT, UI_PAL_ERROR,
61	};
62	static const char *const s_state_text[] = {
63	  /* Mirrors pet_status_view's captions — and, critically, sticks to glyphs
64	   * present in the CP MiSans 16 subset (the old "粒子·" prefix used 粒/子,
65	   * which are NOT in the trimmed CP font and rendered as tofu on-device). */
66	  "待机", "聆听中", "思考中", "执行中", "等待确认", "出错了",
67	};
68	
69	/* Per-state physics knobs:
70	 *   perturb  — LCG noise amplitude fed into velocity (q8 units)
71	 *   swirl    — tangential bias strength (rotation; +CW, -CCW)
72	 *   radial   — radial bias (+outward / -inward)
73	 *   damp     — velocity retention per tick (0..256) */
74	typedef struct {
75	  int32_t perturb;
76	  int32_t swirl;
77	  int32_t radial;
78	  int32_t damp;
79	} phys_t;
80	
81	static const phys_t s_phys[] = {
82	  [PARTICLE_STATE_IDLE]      = { 10,   4,   0, 248 },  /* gentle drift */
83	  [PARTICLE_STATE_LISTENING] = { 16,  10, -18, 244 },  /* inward + slow swirl */
84	  [PARTICLE_STATE_THINKING] = { 20,  34,   0, 250 },  /* fast swirl */
85	  [PARTICLE_STATE_EXECUTING] = { 28,  -8,  26, 246 }, /* outward burst */
86	  [PARTICLE_STATE_WAITING]   = {  4,   2,   0, 220 },  /* near-frozen pulse */
87	  [PARTICLE_STATE_ERROR]     = { 90,   0,   0, 252 },  /* chaotic scatter */
88	};
89	
90	struct particle_s {
91	  int32_t x, y;          /* position, pixels */
92	  int32_t vx, vy;        /* velocity, q8 (256 = 1px/tick) */
93	  uint32_t lcg;          /* per-particle pseudo-noise state */
94	  int32_t last_rx, last_ry;  /* last rendered top-left; skip set_pos if unchanged */
95	};
96	
97	struct pf_state_s {
98	  bool initialized;
99	  bool visible;
100	  enum particle_state state;
101	  lv_obj_t *screen;
102	  lv_obj_t *guide_ring;  /* faint lv_arc, shared motif with pet */
103	  lv_obj_t *core;        /* central pulsing circle */
104	  lv_obj_t *particles[N_PARTICLES];
105	  lv_obj_t *label;
106	  lv_obj_t *prev_screen;
107	  struct particle_s p[N_PARTICLES];
108	  lv_timer_t *timer;
109	  uint32_t tick;
110	  /* display geometry (pixels) */
111	  int32_t cx, cy, R, R_sq;
112	};
113	
114	static struct pf_state_s s_pf;
115	
116	/* ---------- LCG (per-particle deterministic pseudo-noise) ---------- */
117	
118	static inline int32_t lcg_next(uint32_t *s)
119	{
120	  *s = (*s * 1103515765u + 12345u) & 0x7fffffffu;
121	  return (int32_t)(*s >> 15) - 16384;   /* [-16384, 16383] */
122	}
123	
124	/* ---------- physics step (runs in LVGL thread via timer) ---------- */
125	
126	static void physics_step(void)
127	{
128	  const phys_t *ph = &s_phys[s_pf.state];
129	  int32_t cx = s_pf.cx, cy = s_pf.cy, R_sq = s_pf.R_sq;
130	  int32_t damp = ph->damp;
131	  int32_t perturb = ph->perturb;
132	  int32_t swirl = ph->swirl;
133	  int32_t radial = ph->radial;
134	
135	  for (int i = 0; i < N_PARTICLES; i++)
136	    {
137	      struct particle_s *p = &s_pf.p[i];
138	      int32_t dx = p->x - cx;
139	      int32_t dy = p->y - cy;
140	
141	      /* LCG noise → small velocity kick (perturb in q8; noise normalized to ~[-1,1] px). */
142	      int32_t nx = lcg_next(&p->lcg);
143	      int32_t ny = lcg_next(&p->lcg);
144	      p->vx += (nx * perturb) / 16384;
145	      p->vy += (ny * perturb) / 16384;
146	
147	      /* Swirl: tangential bias ∝ radial offset (unnormalized → faster swirl
148	       * farther out, reads as rotation). tang = (-dy, dx). */
149	      p->vx += (-dy * swirl) / 64;
150	      p->vy += ( dx * swirl) / 64;
151	
152	      /* Radial bias: outward (+) pulls particles to the rim, inward (-) sucks
153	       * them toward the core. */
154	      p->vx += (dx * radial) / 64;
155	      p->vy += (dy * radial) / 64;
156	
157	      /* Damping. */
158	      p->vx = (p->vx * damp) / 256;
159	      p->vy = (p->vy * damp) / 256;
160	
161	      /* Speed clamp so chaos stays bounded. */
162	      int32_t vmax = 3 * ONE_PX;
163	      if (p->vx >  vmax) p->vx =  vmax;
164	      if (p->vx < -vmax) p->vx = -vmax;
165	      if (p->vy >  vmax) p->vy =  vmax;
166	      if (p->vy < -vmax) p->vy = -vmax;
167	
168	      /* Advance. */
169	      int32_t nxp = p->x + (p->vx >> VEL_Q);
170	      int32_t nyp = p->y + (p->vy >> VEL_Q);
171	
172	      /* Round-bound bounce: if next step leaves the disc, reverse velocity
173	       * (cheap reflection) and don't move this tick. dist_sq in pixel units
174	       * fits in int32 (max ~217k). */
175	      int32_t ddx = nxp - cx;
176	      int32_t ddy = nyp - cy;
177	      int32_t dsq = ddx * ddx + ddy * ddy;
178	      if (dsq > R_sq)
179	        {
180	          p->vx = -p->vx;
181	          p->vy = -p->vy;
182	        }
183	      else
184	        {
185	          p->x = nxp;
186	          p->y = nyp;
187	        }
188	
189	      /* Render — only invalidate when the integer pixel position actually
190	       * changes.  Particles move sub-pixel most ticks (q8 velocity), so an
191	       * unconditional set_pos would invalidate 18 regions every 33 ms even
192	       * when nothing visibly moved.  On flush paths that can't keep up
193	       * (qemu goldfish headless fb) the constant re-invalidation starves the
194	       * flush so the screen never reaches the framebuffer.  Skipping no-op
195	       * moves collapses invalidations to only real pixel crossings. */
196	      lv_obj_t *o = s_pf.particles[i];
197	      if (o)
198	        {
199	          int32_t rx = p->x - (PARTICLE_DIAM / 2);
200	          int32_t ry = p->y - (PARTICLE_DIAM / 2);
201	          if (rx != p->last_rx || ry != p->last_ry)
202	            {
203	              lv_obj_set_pos(o, rx, ry);
204	              p->last_rx = rx;
205	              p->last_ry = ry;
206	            }
207	        }
208	    }
209	
210	  /* Core pulse: opacity breathing driven by tick (no lv_anim to keep the
211	   * pulsing phase-locked to the physics tick). */
212	  if (s_pf.core)
213	    {
214	      uint32_t t = s_pf.tick & 63;            /* 0..63 */
215	      int32_t tri = (t < 32) ? t : (63 - t);  /* triangle 0..31 */
216	      lv_opa_t opa = LV_OPA_60 + (tri * (LV_OPA_COVER - LV_OPA_60)) / 31;
217	      lv_obj_set_style_opa(s_pf.core, opa, 0);
218	    }
219	
220	  s_pf.tick++;
221	}
