252	/**
253	 * Add a message to the chat history ring buffer.
254	 *
255	 * When count < CHAT_HISTORY_MAX, writes at head and increments count.
256	 * When count == CHAT_HISTORY_MAX, overwrites the oldest message and
257	 * deletes its LVGL bubble widget if present.
258	 *
259	 * Text is truncated to LVGL_UI_MSG_MAX_LEN - 1 bytes with explicit
260	 * NUL termination (rule coding-9), UTF-8-aware so a multi-byte char is
261	 * never split in half.
262	 *
263	 * Returns pointer to the newly written slot (inside the ring buffer,
264	 * no stack allocation of chat_msg_t — rule coding-6).
265	 */
266	static chat_msg_t* chat_history_add(chat_history_t* h, const char* text, bool is_user)
267	{
268	    chat_msg_t* slot = &h->msgs[h->head];
269	
270	    /* When buffer is full, recycle the oldest slot */
271	    if (h->count == CHAT_HISTORY_MAX) {
272	        if (slot->bubble) {
273	            lv_obj_del(slot->bubble);
274	            slot->bubble = NULL;
275	        }
276	    } else {
277	        h->count++;
278	    }
279	
280	    /* Write message text with UTF-8-aware truncation */
281	    chat_view_copy_text(slot->text, text, LVGL_UI_MSG_MAX_LEN);
282	
283	    slot->is_user = is_user;
284	    slot->bubble = NULL;
285	
286	    h->head = (h->head + 1) % CHAT_HISTORY_MAX;
287	
288	    return slot;
289	}
