373	int lvgl_ui_channel_init(void)
374	{
375	    int chat_h;
376	    int ret = 0;
377	    /* Display geometry — queried from the active display so the layout
378	     * adapts to both the 466×466 round watch (real hardware) and the
379	     * 1280×800 rectangle (qemu). Falls back to the 466 constants when
380	     * no display is registered yet. */
381	    lv_coord_t disp_w = LVGL_UI_SCREEN_W;
382	    lv_coord_t disp_h = LVGL_UI_SCREEN_H;
383	
384	    /* Idempotent: already initialized */
385	    if (s_state.initialized) {
386	        return 0;
387	    }
388	
389	    syslog(LOG_INFO, "[%s] init\n", TAG);
390	
391	    /* If LVGL is not yet initialized (qemu: no miwear/launcher owns it),
392	     * bring it up ourselves: lv_init + lv_nuttx_init(/dev/fb0) + a
393	     * lv_timer_handler loop thread.  On real hardware where miwear already
394	     * did this, lv_is_initialized() is true and we skip — only creating
395	     * widgets on the existing display, as before. */
396	    if (!lv_is_initialized()) {
397	        lv_nuttx_dsc_t dsc;
398	
399	        syslog(LOG_INFO, "[%s] LVGL not initialized; self-init on /dev/fb0\n", TAG);
400	
401	        lv_init();
402	        lv_nuttx_dsc_init(&dsc);
403	        /* fb_path defaults to /dev/fb0 in lv_nuttx_dsc_init; GOLDFISH_GPU_FB
404	         * provides it on qemu-arm64-v8a-ap. */
405	        lv_nuttx_init(&dsc, &s_lv_result);
406	
407	        if (s_lv_result.disp == NULL) {
408	            syslog(LOG_ERR, "[%s] lv_nuttx_init failed (no display)\n", TAG);
409	            ret = -EIO;
410	            goto cleanup;
411	        }
412	
413	        /* Start the LVGL event loop thread (miwear would own this on real
414	         * hardware; on qemu we run it ourselves). */
415	        s_lv_loop_running = true;
416	        /* LVGL rendering + CJK (SIMSUN/FreeType) glyph rasterization needs a
417	         * deep stack; the default pthread stack overflows -> recursive
418	         * assert. Use an explicitly sized stack. */
419	        pthread_attr_t lv_attr;
420	        pthread_attr_init(&lv_attr);
421	        pthread_attr_setstacksize(&lv_attr, AGENT_LVGL_UI_STACK);
422	        if (pthread_create(&s_lv_loop_tid, &lv_attr, lv_loop_thread, NULL) != 0) {
423	            syslog(LOG_ERR, "[%s] LVGL loop thread create failed\n", TAG);
424	            lv_nuttx_deinit(&s_lv_result);
425	            s_lv_loop_running = false;
426	            ret = -EIO;
427	            goto cleanup;
428	        }
429	        s_lv_owned = true;
430	        syslog(LOG_INFO, "[%s] LVGL self-init OK, loop thread started\n", TAG);
431	    } else {
432	        syslog(LOG_INFO, "[%s] LVGL already initialized (system owns it)\n", TAG);
433	    }
434	
435	    /* Query the real display resolution so the layout adapts to the
436	     * actual screen (466 round watch on hardware, 1280×800 on qemu)
437	     * instead of always using the 466 constants. */
438	    lv_display_t* disp = lv_display_get_default();
439	    if (disp) {
440	        lv_coord_t rw = lv_display_get_horizontal_resolution(disp);
441	        lv_coord_t rh = lv_display_get_vertical_resolution(disp);
442	        if (rw > 0 && rh > 0) {
443	            disp_w = rw;
444	            disp_h = rh;
445	            syslog(LOG_INFO, "[%s] display %dx%d\n", TAG, disp_w, disp_h);
446	        }
447	    }
448	
449	    /* Scale the 466×466 reference layout against the actual panel width (q8)
450	     * so the chat UI keeps sensible proportions on the real 240×296 BK7258
451	     * round LCD — the fixed 466 constants previously left a ~74px chat area,
452	     * a ~112px (half-screen) PTT button and a close button outside the
453	     * visible circle.  On the 466 reference (disp_w==466) lscale==256 and all
454	     * values equal the original constants. */
455	    int32_t lscale   = (disp_w * 256) / LVGL_UI_SCREEN_W;
456	    int32_t pad_h    = (LVGL_UI_PADDING_H      * lscale) / 256;
457	    int32_t pad_top  = (LVGL_UI_PADDING_TOP    * lscale) / 256;
458	    int32_t pad_bot  = (LVGL_UI_PADDING_BOTTOM * lscale) / 256;
459	    int32_t ptt_size = (LVGL_UI_PTT_SIZE       * lscale) / 256;
460	    int32_t ptt_gap  = (20 * lscale) / 256;
461	    /* The close button lives in the upper-right arc of the inscribed circle.
462	     * On the 240×296 panel the circle (R≈112) starts ~36px below the top
463	     * edge, so a flat 466-scaled offset would land it in the bezel.  Anchor
464	     * it with display fractions instead (verified inside the circle at both
465	     * 240×296 and 466×466). */
466	    int32_t close_x  = disp_w / 6;
467	    int32_t close_y  = disp_h / 5;
468	
469	    /* Create main screen with dark background */
470	    s_state.screen = lv_obj_create(NULL);
471	    if (!s_state.screen) {
472	        syslog(LOG_ERR, "[%s] screen create failed\n", TAG);
473	        ret = -EIO;
474	        goto cleanup;
475	    }
476	
477	    lv_obj_set_style_bg_color(s_state.screen, lv_color_hex(UI_PAL_BG), 0);
478	    lv_obj_set_style_bg_opa(s_state.screen, LV_OPA_COVER, 0);
479	    /* Do NOT call lv_screen_load() here — we load the screen on
480	     * demand when the user activates the chat UI, to avoid
481	     * hijacking the system's current screen at boot. */
482	
483	    /* Default text font: the app-owned statically-compiled MiSans-16 CJK font
484	     * (3755 GB2312-1 common chars + ASCII + fullwidth punctuation, baked into
485	     * the binary via lv_font_conv — zero runtime malloc/rasterization) so
486	     * Agent reply Chinese text renders on qemu with full coverage and cannot
487	     * corrupt the heap.  Falls back to SimSun-16 (1000 chars) then Montserrat. */
488	    lv_obj_set_style_text_font(s_state.screen, &lv_font_misans_16_cjk, 0);
489	
490	    /* Step 5: Create Chat View container */
491	    chat_h = disp_h - pad_top - pad_bot - ptt_size - ptt_gap;
492	
493	    s_state.chat_list = lv_obj_create(s_state.screen);
494	    if (!s_state.chat_list) {
495	        syslog(LOG_ERR, "[%s] chat_list create failed\n", TAG);
496	        ret = -EIO;
497	        goto cleanup;
498	    }
499	
500	    lv_obj_set_size(s_state.chat_list,
501	        disp_w - 2 * pad_h, chat_h);
502	    lv_obj_align(s_state.chat_list, LV_ALIGN_TOP_MID, 0, pad_top);
503	    lv_obj_set_scroll_dir(s_state.chat_list, LV_DIR_VER);
504	    lv_obj_set_flex_flow(s_state.chat_list, LV_FLEX_FLOW_COLUMN);
505	    lv_obj_set_style_pad_row(s_state.chat_list, LVGL_UI_CHAT_GAP, 0);
506	    lv_obj_set_style_bg_opa(s_state.chat_list, LV_OPA_TRANSP, 0);
507	    lv_obj_set_style_border_width(s_state.chat_list, 0, 0);
508	    lv_obj_set_style_pad_left(s_state.chat_list, 4, 0);
509	    lv_obj_set_style_pad_right(s_state.chat_list, 4, 0);
510	    lv_obj_set_style_pad_top(s_state.chat_list, 4, 0);
511	    lv_obj_set_style_pad_bottom(s_state.chat_list, 4, 0);
512	    lv_obj_set_scrollbar_mode(s_state.chat_list, LV_SCROLLBAR_MODE_OFF);
513	    lv_obj_add_flag(s_state.chat_list, LV_OBJ_FLAG_SCROLL_MOMENTUM);
514	
515	    /* Step 6: Create PTT Button */
516	    s_state.ptt_btn = lv_btn_create(s_state.screen);
517	    if (!s_state.ptt_btn) {
518	        syslog(LOG_ERR, "[%s] ptt_btn create failed\n", TAG);
519	        ret = -EIO;
520	        goto cleanup;
521	    }
522	
523	    lv_obj_set_size(s_state.ptt_btn, ptt_size, ptt_size);
524	    lv_obj_align(s_state.ptt_btn, LV_ALIGN_BOTTOM_MID, 0, -pad_bot);
525	    lv_obj_set_style_radius(s_state.ptt_btn, ptt_size / 2, 0);
526	    lv_obj_set_style_bg_color(s_state.ptt_btn, lv_color_hex(UI_PAL_ACCENT), 0);
527	    lv_obj_set_style_shadow_width(s_state.ptt_btn, 12, 0);
528	    lv_obj_set_style_shadow_color(s_state.ptt_btn, lv_color_hex(UI_PAL_ACCENT), 0);
529	    lv_obj_set_style_shadow_opa(s_state.ptt_btn, LV_OPA_40, 0);
530	
531	    s_state.ptt_label = lv_label_create(s_state.ptt_btn);
532	    if (!s_state.ptt_label) {
533	        syslog(LOG_ERR, "[%s] ptt_label create failed\n", TAG);
534	        ret = -EIO;
535	        goto cleanup;
536	    }
537	
538	    /* "请说" (PTT_ICON_MIC): a plain MiSans-CJK text label instead of a
539	     * microphone glyph — the emoji/font-awesome glyphs aren't in the CP font
540	     * subset and render as rectangles. White-on-orange matches the user
541	     * bubble's text color. */
542	    lv_label_set_text(s_state.ptt_label, PTT_ICON_MIC);
543	    lv_obj_set_style_text_color(s_state.ptt_label, lv_color_white(), 0);
544	    lv_obj_center(s_state.ptt_label);
545	
546	    lv_obj_add_event_cb(s_state.ptt_btn, ptt_btn_event_cb, LV_EVENT_ALL, NULL);
547	
548	    /* Step 7: Create Recording Indicator (initially hidden) */
549	    s_state.rec_indicator = lv_label_create(s_state.screen);
550	    if (!s_state.rec_indicator) {
551	        syslog(LOG_ERR, "[%s] rec_indicator create failed\n", TAG);
552	        ret = -EIO;
553	        goto cleanup;
554	    }
555	
556	    lv_label_set_text(s_state.rec_indicator, "");
557	    lv_obj_align_to(s_state.rec_indicator, s_state.ptt_btn, LV_ALIGN_OUT_TOP_MID, 0, -8);
558	    lv_obj_add_flag(s_state.rec_indicator, LV_OBJ_FLAG_HIDDEN);
559	
560	    /* Step 7b: Create Close Button (top-right corner) */
561	    s_state.close_btn = lv_btn_create(s_state.screen);
562	    if (!s_state.close_btn) {
563	        syslog(LOG_ERR, "[%s] close_btn create failed\n", TAG);
564	        ret = -EIO;
565	        goto cleanup;
566	    }
567	
568	    lv_obj_set_size(s_state.close_btn, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
569	    /* A compact floating "关闭" label anchored inside the upper-right arc of
570	     * the round bezel (close_x/close_y are display-fraction derived above). */
571	    lv_obj_align(s_state.close_btn, LV_ALIGN_TOP_MID, close_x, close_y);
572	    lv_obj_set_style_bg_opa(s_state.close_btn, LV_OPA_TRANSP, 0);
573	    lv_obj_set_style_border_width(s_state.close_btn, 0, 0);
574	    lv_obj_set_style_shadow_opa(s_state.close_btn, LV_OPA_TRANSP, 0);
575	    lv_obj_set_style_pad_all(s_state.close_btn, 4, 0);
576	
577	    lv_obj_t* close_label = lv_label_create(s_state.close_btn);
578	    if (close_label) {
579	        lv_label_set_text(close_label, CLOSE_BTN_TEXT);
580	        lv_obj_set_style_text_color(close_label, lv_color_hex(0x999999), 0);
581	        lv_obj_center(close_label);
582	    }
583	
584	    lv_obj_add_event_cb(s_state.close_btn, close_btn_event_cb, LV_EVENT_CLICKED, NULL);
585	
586	    /* Step 8: Initialize chat history and mutex */
587	    memset(&s_state.history, 0, sizeof(chat_history_t));
588	    pthread_mutex_init(&s_state.lock, NULL);
589	
590	    s_state.initialized = true;
591	    syslog(LOG_INFO, "[%s] init OK\n", TAG);
592	
593	#ifdef CONFIG_AI_AGENT_PET_STATUS
594	    /* Build the pet status ring home screen (M7 差异化页).  It is NOT loaded
595	     * here — cp_ui_main (or the AP via RPMsg) decides when to show it.  The
596	     * idle-yield timer runs in the LVGL thread and only fires when the chat
597	     * screen owns the foreground. */
598	    (void)pet_status_view_init();
599	    /* Surface the pet as the boot/home screen immediately.  On CP this is
600	     * idempotent with cp_ui_main's explicit show(); on qemu (no cp_ui_main,
601	     * no AP→CP RPMsg) it is the only thing that brings the pet up at boot. */
602	    pet_status_view_show();
603	    s_pet_idle_timer = lv_timer_create(pet_idle_timer_cb, 1000, NULL);
604	    if (s_pet_idle_timer)
605	      {
606	        lv_timer_set_repeat_count(s_pet_idle_timer, -1);
607	      }
608	    pet_idle_reset();
609	#endif
610	#ifdef CONFIG_AI_AGENT_PARTICLE_FLOW
611	    /* M7 差异化页 ②: build the particle flow screen (NOT loaded — the pet is
612	     * the cold-start home screen; the particle page is reached via set_page 1).
613	     * Init here so it is ready to show without a per-call create latency. */
614	    (void)particle_flow_view_init();
615	#endif
616	#if defined(CONFIG_AI_AGENT_PET_STATUS) && defined(CONFIG_AI_AGENT_PARTICLE_FLOW)
617	    /* Idle auto-rotate between pet ① and particle ② (UI方案.md §2.4).
618	     * 1 s period polls the idle condition; the cb self-throttles to
619	     * ROTATE_INTERVAL_MS between actual switches. */
620	    s_rotate_timer = lv_timer_create(rotate_timer_cb, 1000, NULL);
621	    if (s_rotate_timer)
622	      {
623	        lv_timer_set_repeat_count(s_rotate_timer, -1);
624	      }
625	    rotate_idle_reset();
626	#endif
627	    return 0;
628	
629	cleanup:
630	    /* Release resources in reverse order (coding-2) */
631	
632	    if (s_state.screen) {
633	        lv_obj_del(s_state.screen);
634	        s_state.screen = NULL;
635	        /* Child widgets are deleted with the screen */
636	        s_state.chat_list = NULL;
637	        s_state.ptt_btn = NULL;
638	        s_state.ptt_label = NULL;
639	        s_state.rec_indicator = NULL;
640	        s_state.close_btn = NULL;
641	    }
642	
643	    syslog(LOG_ERR, "[%s] init failed (rc=%d)\n", TAG, ret);
644	    return ret;
645	}
