670	/* Semaphore for synchronizing async stop with LVGL thread */
671	static sem_t s_stop_sem;
672	
673	/* Internal cleanup — must be called from LVGL thread context */
674	static void lvgl_ui_do_cleanup(void)
675	{
676	    int i;
677	
678	    if (s_state.screen) {
679	        /* If our screen is the active screen, restore the previous
680	         * (launcher) screen first.  Deleting the active screen without
681	         * loading another one leaves LVGL with no valid screen — the
682	         * next lv_timer_handler() call crashes with a MemManage fault
683	         * (NULL pointer dereference at offset 0x32 in lv_obj_t). */
684	        if (s_state.screen_visible && s_state.prev_screen) {
685	            lv_screen_load(s_state.prev_screen);
686	        }
687	
688	        lv_obj_del(s_state.screen);
689	        s_state.screen = NULL;
690	    }
691	
692	    s_state.screen_visible = false;
693	    s_state.prev_screen = NULL;
694	
695	    s_state.chat_list = NULL;
696	    s_state.ptt_btn = NULL;
697	    s_state.ptt_label = NULL;
698	    s_state.rec_indicator = NULL;
699	    s_state.close_btn = NULL;
700	
701	    for (i = 0; i < CHAT_HISTORY_MAX; i++) {
702	        s_state.history.msgs[i].bubble = NULL;
703	    }
704	
705	    s_state.history.head = 0;
706	    s_state.history.count = 0;
707	
708	    /* Note: when we self-initialized LVGL (s_lv_owned, qemu case), the
709	     * lv_timer_handler loop thread is intentionally left running — it is
710	     * torn down only when the ai_agent process exits.  Stopping it from
711	     * within cleanup (which itself runs in that loop thread via
712	     * lv_async_call) would self-deadlock.  Widget deletion above is safe
713	     * because the loop is still alive to process it. */
714	}
715	
716	static void stop_screen_async_cb(void* data)
717	{
718	    (void)data;
719	
720	    lvgl_ui_do_cleanup();
721	    sem_post(&s_stop_sem);
722	}
723	
724	/* Stop from within the LVGL thread (e.g. close button callback).
725	 * Performs cleanup directly — no async scheduling needed. */
726	void lvgl_ui_channel_stop_sync(void)
727	{
728	    if (!s_state.initialized || !s_state.running) {
729	        return;
730	    }
731	
732	    syslog(LOG_INFO, "[%s] stopping (sync)\n", TAG);
733	
734	    s_state.running = false;
735	    lvgl_ui_do_cleanup();
736	    pthread_mutex_destroy(&s_state.lock);
