742	/* Stop from an external thread (e.g. velaquit shutdown).
743	 * Schedules cleanup in the LVGL thread to avoid racing with the
744	 * miwear/launcher event loop. */
745	void lvgl_ui_channel_stop(void)
746	{
747	    /* No-op if not initialized or not running */
748	    if (!s_state.initialized || !s_state.running) {
749	        return;
750	    }
751	
752	    syslog(LOG_INFO, "[%s] stopping\n", TAG);
753	
754	    /* Mark as not running first — prevents callbacks (PTT, close_btn,
755	     * chat_view_add_message) from touching widgets during teardown. */
756	    s_state.running = false;
757	
758	    /* Schedule cleanup in the LVGL thread to avoid racing with the
759	     * miwear/launcher event loop.  Direct lv_obj_del from the
760	     * shutdown thread causes a MemManage fault because the LVGL
761	     * thread may be mid-render on the same objects. */
762	    sem_init(&s_stop_sem, 0, 0);
763	    lv_async_call(stop_screen_async_cb, NULL);
764	
765	    /* Wait for LVGL thread to complete the deletion (timeout 2s) */
766	    struct timespec ts;
767	
768	    clock_gettime(CLOCK_REALTIME, &ts);
769	    ts.tv_sec += 2;
770	
771	    if (sem_timedwait(&s_stop_sem, &ts) != 0) {
772	        syslog(LOG_WARNING,
773	            "[%s] async stop timed out, forcing cleanup\n", TAG);
774	        /* Fallback: NULL out pointers without deleting (leak is
775	         * acceptable during shutdown to avoid crash). */
776	        s_state.screen = NULL;
777	        s_state.chat_list = NULL;
778	        s_state.ptt_btn = NULL;
779	        s_state.ptt_label = NULL;
780	        s_state.rec_indicator = NULL;
781	        s_state.close_btn = NULL;
782	    }
783	
784	    sem_destroy(&s_stop_sem);
785	
786	    /* Destroy the mutex */
787	    pthread_mutex_destroy(&s_state.lock);
788	
789	    s_state.initialized = false;
790	
791	    syslog(LOG_INFO, "[%s] stopped\n", TAG);
792	}
