859	int lvgl_ui_channel_send(const char* text)
860	{
861	    int ret;
862	    async_msg_t* payload;
863	
864	    /* Parameter validation: NULL or empty string */
865	    if (!text || text[0] == '\0') {
866	        syslog(LOG_ERR, "[%s] send: invalid text (NULL or empty)\n", TAG);
867	        return -EINVAL;
868	    }
869	
870	    /* Check channel readiness */
871	    if (!s_state.initialized || !s_state.running) {
872	        syslog(LOG_ERR, "[%s] send: channel not ready (init=%d run=%d)\n",
873	            TAG, s_state.initialized, s_state.running);
874	        return -EINVAL;
875	    }
876	
877	    /* Auto-show chat screen on first Agent reply */
878	    if (!s_state.screen_visible) {
879	        lvgl_ui_channel_show();
880	    }
881	
882	    /* Schedule bubble creation in LVGL thread via lv_async_call.
883	     * This avoids the "Invalidate area is not allowed during rendering"
884	     * assertion crash that occurs when we create LVGL widgets from
885	     * the agent dispatch thread while miwear's LVGL thread is
886	     * mid-render. */
887	    payload = malloc(sizeof(async_msg_t));
888	    if (!payload) {
889	        syslog(LOG_ERR, "[%s] send: async payload alloc failed\n", TAG);
890	        return -ENOMEM;
891	    }
892	
893	    chat_view_copy_text(payload->text, text, LVGL_UI_MSG_MAX_LEN);
894	    payload->is_user = false;
895	
896	    lv_async_call(chat_view_add_message_async_cb, payload);
897	
898	    /* TTS is blocking — run after scheduling the UI update */
899	    ret = voice_channel_speak(text);
900	    if (ret != 0) {
901	        syslog(LOG_ERR, "[%s] voice_channel_speak failed (rc=%d)\n", TAG, ret);
902	    }
903	
904	    return 0;
905	}
