1367	static void ptt_btn_event_cb(lv_event_t* e)
1368	{
1369	    lv_event_code_t code = lv_event_get_code(e);
1370	
1371	    /* Single-click toggle: first click starts recording, second stops */
1372	    if (code != LV_EVENT_CLICKED) {
1373	        return;
1374	    }
1375	
1376	    pthread_mutex_lock(&s_state.lock);
1377	
1378	    if (s_state.is_processing) {
1379	        pthread_mutex_unlock(&s_state.lock);
1380	        return;
1381	    }
1382	
1383	    if (!s_state.is_recording) {
1384	        /* First click: start recording */
1385	        int ret = voice_channel_start();
1386	        if (ret != 0) {
1387	            syslog(LOG_ERR, "[%s] voice_channel_start failed (rc=%d)\n", TAG, ret);
1388	            pthread_mutex_unlock(&s_state.lock);
1389	            chat_view_add_message("录音启动失败", false, 0);
1390	            return;
1391	        }
1392	
1393	        s_state.is_recording = true;
1394	        pthread_mutex_unlock(&s_state.lock);
1395	
1396	        recording_indicator_start();
1397	    } else {
1398	        /* Second click: stop recording and process */
1399	        s_state.is_recording = false;
1400	        s_state.is_processing = true;
1401	        pthread_mutex_unlock(&s_state.lock);
1402	
1403	        recording_indicator_show_processing();
1404	
1405	        /* Stop recording and get ASR text synchronously */
1406	        char asr_text[LVGL_UI_MSG_MAX_LEN];
1407	        int ret = voice_channel_stop_with_text(asr_text,
1408	            sizeof(asr_text));
1409	
1410	        if (ret != 0) {
1411	            syslog(LOG_ERR,
1412	                "[%s] voice_channel_stop_with_text failed (rc=%d)\n",
1413	                TAG, ret);
1414	            goto done;
1415	        }
1416	
1417	        if (asr_text[0] == '\0') {
1418	            chat_view_add_message("未识别到语音", false, 0);
1419	            goto done;
1420	        }
1421	
1422	        /* Route through the single dispatch point so the destination stays
1423	         * out of this file: with no sink registered the utterance goes to the
1424	         * chat bus exactly as before, and a product that registered one owns
1425	         * it instead.  This file must not learn which consumer exists.
1426	         */
1427	
1428	        voice_channel_dispatch(asr_text);
1429	        chat_view_add_message(asr_text, true, 0);
1430	
1431	    done:
1432	        pthread_mutex_lock(&s_state.lock);
1433	        s_state.is_processing = false;
1434	        pthread_mutex_unlock(&s_state.lock);
1435	        recording_indicator_stop();
1436	    }
1437	}
