88	/* LVGL v9 exec_cb signature is lv_anim_exec_xcb_t = void(*)(void*, lv_anim_value_t),
89	 * i.e. the first arg is the animated var (void*), NOT lv_obj_t* nor lv_anim_t*.
90	 * We cast to lv_obj_t* inside for the lv_obj and lv_arc calls. */
91	/* Spinner: a 90° segment rotating (THINKING / LISTENING). value = start angle. */
92	static void spin_cb(void *obj, int32_t v)
93	{
94	  lv_obj_t *o = (lv_obj_t *)obj;
95	  lv_arc_set_angles(o, v, v + 90);
96	}
