98	/* Growing fill: indicator grows 0→360 (EXECUTING). value = end angle. */
99	static void fill_cb(void *obj, int32_t v)
100	{
101	  lv_obj_t *o = (lv_obj_t *)obj;
102	  lv_arc_set_angles(o, 0, v);
103	}
