105	/* Breathing: sprite opacity pulses (IDLE). value 0..100. */
106	static void breathe_cb(void *obj, int32_t v)
107	{
108	  lv_obj_t *o = (lv_obj_t *)obj;
109	  /* 100% → 255, 0% → 190 (gentle). */
110	  lv_obj_set_style_opa(o, LV_OPA_COVER - (v * (LV_OPA_COVER - 190)) / 100, 0);
111	}
