113	/* Float: gentle vertical bob (IDLE, layered with the opacity breathe so the
114	 * idle pet feels alive rather than a static icon). value 0..100. */
115	static void float_cb(void *obj, int32_t v)
116	{
117	  lv_obj_t *o = (lv_obj_t *)obj;
118	  /* Triangle 0→+2→0→-2→0 across one cycle — a ±2px bob on a 96px sprite. */
119	  int32_t amp;
120	  if (v < 25)      amp = (v * 2) / 25;
121	  else if (v < 50) amp = ((50 - v) * 2) / 25;
122	  else if (v < 75) amp = -((v - 50) * 2) / 25;
123	  else             amp = -((100 - v) * 2) / 25;
124	  lv_obj_set_style_translate_y(o, amp, 0);
125	}
