232	static void apply_state_async_cb(void *data)
233	{
234	  enum particle_state st = (enum particle_state)(intptr_t)data;
235	  if (!s_pf.initialized) return;
236	  s_pf.state = st;
237	  uint32_t color = s_state_color[st];
238	
239	  for (int i = 0; i < N_PARTICLES; i++)
240	    {
241	      if (s_pf.particles[i])
242	        {
243	          lv_obj_set_style_bg_color(s_pf.particles[i], lv_color_hex(color), 0);
244	        }
245	    }
246	  if (s_pf.core)
247	    {
248	      lv_obj_set_style_bg_color(s_pf.core, lv_color_hex(color), 0);
249	    }
250	  if (s_pf.label)
251	    {
252	      lv_label_set_text(s_pf.label, s_state_text[st]);
253	    }
254	  syslog(LOG_INFO, "[%s] state → %s\n", TAG, s_state_text[st]);
255	}
