17	/*
18	 * particle_flow_view.c — 圆屏粒子流（M7 差异化页 ②，纯 LVGL）。
19	 *
20	 * 设计见 particle_flow_view.h。18 颗粒子在圆屏内做受控布朗流动，中央核心
21	 * 脉动；态切换改变粒子色 + 流向偏置（内聚 / 外散 / 旋转 / 混沌）+ 核心脉速。
22	 * 视觉与宠物脸+环刻意不同（抽象能量流），借同一套 agent 状态镜像语义。
23	 *
24	 * 物理：整数定点，位置以像素为单位，速度以 q8（256 = 1px/tick）为单位，
25	 * 每 tick (33ms≈30fps) 由 lv_timer 在 LVGL 线程推进；边界反弹用速度反转 +
26	 * 位置钳位（距离平方比较，无 sqrt）。无浮点 / math.h 依赖，跨核可移植。
27	 * 随机扰动用每粒子独立 LCG（确定性伪噪声，免 rand 依赖）。
28	 */
29	
30	#include <nuttx/config.h>
31	
32	#ifdef CONFIG_AI_AGENT_PARTICLE_FLOW
33	
34	#include "ui/particle_flow_view.h"
