432

380	     * no display is registered yet. */
381	    lv_coord_t disp_w = LVGL_UI_SCREEN_W;
382	    lv_coord_t disp_h = LVGL_UI_SCREEN_H;
383	
384	    /* Idempotent: already initialized */
385	    if (s_state.initialized) {
386	        return 0;
387	    }
388	
389	    syslog(LOG_INFO, "[%s] init\n", TAG);
390	
391	    /* If LVGL is not yet initialized (qemu: no miwear/launcher owns it),
392	     * bring it up ourselves: lv_init + lv_nuttx_init(/dev/fb0) + a
393	     * lv_timer_handler loop thread.  On real hardware where miwear already
394	     * did this, lv_is_initialized() is true and we skip — only creating
395	     * widgets on the existing display, as before. */
396	    if (!lv_is_initialized()) {
397	        lv_nuttx_dsc_t dsc;
398	
399	        syslog(LOG_INFO, "[%s] LVGL not initialized; self-init on /dev/fb0\n", TAG);
400	
401	        lv_init();
402	        lv_nuttx_dsc_init(&dsc);
403	        /* fb_path defaults to /dev/fb0 in lv_nuttx_dsc_init; GOLDFISH_GPU_FB
404	         * provides it on qemu-arm64-v8a-ap. */
405	        lv_nuttx_init(&dsc, &s_lv_result);
406	
407	        if (s_lv_result.disp == NULL) {
408	            syslog(LOG_ERR, "[%s] lv_nuttx_init failed (no display)\n", TAG);
409	            ret = -EIO;
410	            goto cleanup;
411	        }
412	
413	        /* Start the LVGL event loop thread (miwear would own this on real
414	         * hardware; on qemu we run it ourselves). */
415	        s_lv_loop_running = true;
416	        /* LVGL rendering + CJK (SIMSUN/FreeType) glyph rasterization needs a
417	         * deep stack; the default pthread stack overflows -> recursive
418	         * assert. Use an explicitly sized stack. */
419	        pthread_attr_t lv_attr;
420	        pthread_attr_init(&lv_attr);
421	        pthread_attr_setstacksize(&lv_attr, AGENT_LVGL_UI_STACK);
422	        if (pthread_create(&s_lv_loop_tid, &lv_attr, lv_loop_thread, NULL) != 0) {
423	            syslog(LOG_ERR, "[%s] LVGL loop thread create failed\n", TAG);
424	            lv_nuttx_deinit(&s_lv_result);
425	            s_lv_loop_running = false;
426	            ret = -EIO;
427	            goto cleanup;
428	        }
429	        s_lv_owned = true;
430	        syslog(LOG_INFO, "[%s] LVGL self-init OK, loop thread started\n", TAG);
431	    } else {
432	        syslog(LOG_INFO, "[%s] LVGL already initialized (system owns it)\n", TAG);
433	    }
434	
435	    /* Query the real display resolution so the layout adapts to the
436	     * actual screen (466 round watch on hardware, 1280×800 on qemu)
437	     * instead of always using the 466 constants. */
438	    lv_display_t* disp = lv_display_get_default();
439	    if (disp) {
440	        lv_coord_t rw = lv_display_get_horizontal_resolution(disp);
441	        lv_coord_t rh = lv_display_get_vertical_resolution(disp);
442	        if (rw > 0 && rh > 0) {
443	            disp_w = rw;
444	            disp_h = rh;
445	            syslog(LOG_INFO, "[%s] display %dx%d\n", TAG, disp_w, disp_h);
446	        }
447	    }
448	
449	    /* Scale the 466×466 reference layout against the actual panel width (q8)
450	     * so the chat UI keeps sensible proportions on the real 240×296 BK7258
451	     * round LCD — the fixed 466 constants previously left a ~74px chat area,
452	     * a ~112px (half-screen) PTT button and a close button outside the
453	     * visible circle.  On the 466 reference (disp_w==466) lscale==256 and all
454	     * values equal the original constants. */
455	    int32_t lscale   = (disp_w * 256) / LVGL_UI_SCREEN_W;
456	    int32_t pad_h    = (LVGL_UI_PADDING_H      * lscale) / 256;
457	    int32_t pad_top  = (LVGL_UI_PADDING_TOP    * lscale) / 256;
458	    int32_t pad_bot  = (LVGL_UI_PADDING_BOTTOM * lscale) / 256;
459	    int32_t ptt_size = (LVGL_UI_PTT_SIZE       * lscale) / 256;
460	    int32_t ptt_gap  = (20 * lscale) / 256;
461	    /* The close button lives in the upper-right arc of the inscribed circle.
462	     * On the 240×296 panel the circle (R≈112) starts ~36px below the top
463	     * edge, so a flat 466-scaled offset would land it in the bezel.  Anchor
464	     * it with display fractions instead (verified inside the circle at both
465	     * 240×296 and 466×466). */
466	    int32_t close_x  = disp_w / 6;
467	    int32_t close_y  = disp_h / 5;
468	
469	    /* Create main screen with dark background */
470	    s_state.screen = lv_obj_create(NULL);
471	    if (!s_state.screen) {
472	        syslog(LOG_ERR, "[%s] screen create failed\n", TAG);
473	        ret = -EIO;
474	        goto cleanup;
475	    }
476	
477	    lv_obj_set_style_bg_color(s_state.screen, lv_color_hex(UI_PAL_BG), 0);
478	    lv_obj_set_style_bg_opa(s_state.screen, LV_OPA_COVER, 0);
479	    /* Do NOT call lv_screen_load() here — we load the screen on
480	     * demand when the user activates the chat UI, to avoid
481	     * hijacking the system's current screen at boot. */
482	
483	    /* Default text font: the app-owned statically-compiled MiSans-16 CJK font
484	     * (3755 GB2312-1 common chars + ASCII + fullwidth punctuation, baked into
485	     * the binary via lv_font_conv — zero runtime malloc/rasterization) so
486	     * Agent reply Chinese text renders on qemu with full coverage and cannot
487	     * corrupt the heap.  Falls back to SimSun-16 (1000 chars) then Montserrat. */
488	    lv_obj_set_style_text_font(s_state.screen, &lv_font_misans_16_cjk, 0);
489	
