508	    lv_obj_set_style_pad_left(s_state.chat_list, 4, 0);
509	    lv_obj_set_style_pad_right(s_state.chat_list, 4, 0);
510	    lv_obj_set_style_pad_top(s_state.chat_list, 4, 0);
511	    lv_obj_set_style_pad_bottom(s_state.chat_list, 4, 0);
