611	    /* M7 差异化页 ②: build the particle flow screen (NOT loaded — the pet is
612	     * the cold-start home screen; the particle page is reached via set_page 1).
613	     * Init here so it is ready to show without a per-call create latency. */
614	    (void)particle_flow_view_init();
615	#endif
616	#if defined(CONFIG_AI_AGENT_PET_STATUS) && defined(CONFIG_AI_AGENT_PARTICLE_FLOW)
617	    /* Idle auto-rotate between pet ① and particle ② (UI方案.md §2.4).
618	     * 1 s period polls the idle condition; the cb self-throttles to
619	     * ROTATE_INTERVAL_MS between actual switches. */
620	    s_rotate_timer = lv_timer_create(rotate_timer_cb, 1000, NULL);
621	    if (s_rotate_timer)
622	      {
623	        lv_timer_set_repeat_count(s_rotate_timer, -1);
624	      }
625	    rotate_idle_reset();
626	#endif
627	    return 0;
628	
629	cleanup:
630	    /* Release resources in reverse order (coding-2) */
631	
632	    if (s_state.screen) {
633	        lv_obj_del(s_state.screen);
634	        s_state.screen = NULL;
635	        /* Child widgets are deleted with the screen */
636	        s_state.chat_list = NULL;
637	        s_state.ptt_btn = NULL;
638	        s_state.ptt_label = NULL;
639	        s_state.rec_indicator = NULL;
640	        s_state.close_btn = NULL;
641	    }
