647	int lvgl_ui_channel_start(void)
648	{
649	    if (!s_state.initialized) {
650	        syslog(LOG_ERR, "[%s] start: not initialized\n", TAG);
651	        return -EINVAL;
652	    }
653	
654	    /* Idempotent: already running */
655	    if (s_state.running) {
656	        return 0;
657	    }
658	
659	    s_state.running = true;
660	
661	    /* No dedicated UI thread needed — the system's miwear LVGL event
662	     * loop already calls lv_timer_handler() which processes our widgets.
663	     * We only need to mark ourselves as running so send/PTT callbacks
664	     * know the channel is active. */
665	
666	    syslog(LOG_INFO, "[%s] started\n", TAG);
667	    return 0;
668	}
