794	/* Async callback: load screen inside LVGL thread context */
795	static void show_screen_async_cb(void* data)
796	{
797	    (void)data;
798	    if (!s_state.initialized || !s_state.running || !s_state.screen) {
799	        return;
800	    }
801	    if (s_state.screen_visible) {
802	        return;
803	    }
804	
805	    /* CJK font selection happens at init() time via the statically-compiled
806	     * lv_font_misans_16_cjk (preferred: 3755 GB2312-1 common chars, baked into
807	     * the binary by lv_font_conv — zero runtime malloc, zero rasterization,
808	     * cannot corrupt the heap).  No runtime TTF loading here.
809	     *
810	     * History: we previously used lv_tiny_ttf_create_data() with a runtime
811	     * MiSans TTF, but stb_truetype's MakeGlyphBitmap write path overran its
812	     * output buffer on certain CJK glyphs and corrupted adjacent NuttX mm heap
813	     * chunk metadata, leading to recursive-assert reboots (mm_foreach /
814	     * nxsched_add_readytorun / nxsem_post_slow in the timer IRQ).  Subsetting
815	     * to 857 KB only delayed the crash; the root cause is the rasterizer, so
816	     * we moved to a pre-rasterized static font.  See lv_font_misans_16_cjk.c
817	     * and the fontgen notes in docs. */
818	    /* Already set in init(); nothing to do at show time. */
819	    syslog(LOG_INFO, "[%s] using static MiSans-16 CJK font\n", TAG);
820	
821	    syslog(LOG_INFO, "[%s] loading chat screen\n", TAG);
822	
823	    /* Save the current screen so we can restore it on stop.
824	     * The launcher (miwear) owns this screen — we must not delete it. */
825	    s_state.prev_screen = lv_screen_active();
826	
827	    lv_screen_load(s_state.screen);
828	    s_state.screen_visible = true;
829	
830	#ifdef LVGL_UI_CARD_SELFTEST
831	    /* Debug self-test: inject one card per reply category so all four
832	     * color-bar variants render on a single show_chat.  Remove the
833	     * -DLVGL_UI_CARD_SELFTEST define to disable. */
834	    syslog(LOG_INFO, "[%s] CARD_SELFTEST: injecting sample cards\n", TAG);
835	    chat_view_add_message("这个提交已 MERGED,状态: 正常合入", false, 0);
836	    chat_view_add_message("Jira issue FEEDBACK-149182,经办人: 张文海,More Info", false, 0);
837	    chat_view_add_message("值得合入,建议采纳,yes", false, 0);
838	    chat_view_add_message("这是一条普通回复,用于展示默认灰色色条", false, 0);
839	    chat_view_add_message("你好,这是一条用户消息", true, 0);
840	#endif
841	}
