843	void lvgl_ui_channel_show(void)
844	{
845	    if (!s_state.initialized || !s_state.running) {
846	        syslog(LOG_ERR, "[%s] show: channel not ready\n", TAG);
847	        return;
848	    }
849	
850	    if (s_state.screen_visible) {
851	        return;
852	    }
