975	/* Heap-allocated state for async set_ptt (single int fits in a void* but
976	 * keep a small struct for clarity/future fields). */
977	typedef struct {
978	    int state;
979	} async_ptt_t;
980	
981	static void set_ptt_async_cb(void* data)
982	{
983	    async_ptt_t* p = (async_ptt_t*)data;
984	    if (!p) {
985	        return;
986	    }
987	    if (!s_state.initialized || !s_state.running) {
988	        free(p);
989	        return;
990	    }
991	
992	    switch (p->state) {
993	    case LVGL_UI_PTT_RECORDING:
994	        s_state.is_recording = true;
995	        s_state.is_processing = false;
996	        recording_indicator_start();
997	#ifdef CONFIG_AI_AGENT_PET_STATUS
998	        /* Mirror PTT onto the pet: a recording session reads as "listening". */
999	        pet_status_view_set_state(PET_STATE_LISTENING);
1000	#endif
1001	        break;
1002	    case LVGL_UI_PTT_PROCESSING:
1003	        s_state.is_recording = false;
1004	        s_state.is_processing = true;
1005	        recording_indicator_show_processing();
1006	#ifdef CONFIG_AI_AGENT_PET_STATUS
1007	        pet_status_view_set_state(PET_STATE_THINKING);
1008	#endif
1009	        break;
1010	    case LVGL_UI_PTT_IDLE:
1011	    default:
1012	        s_state.is_recording = false;
1013	        s_state.is_processing = false;
1014	        recording_indicator_stop();
1015	#ifdef CONFIG_AI_AGENT_PET_STATUS
1016	        pet_status_view_set_state(PET_STATE_IDLE);
1017	#endif
1018	        break;
1019	    }
1020	    free(p);
1021	}
