1137	/* Classify an Agent reply text into a coarse card category so the
1138	 * left color bar gives a glanceable cue.  Matching is intentionally
1139	 * simple (case-insensitive substring) — this is a visual hint, not
1140	 * a parser.  Returns the palette color for the matched category. */
1141	static uint32_t chat_view_classify_reply(const char* text)
1142	{
1143	    if (!text || !*text) {
1144	        return LVGL_UI_CARD_COLOR_PLAIN;
1145	    }
1146	
1147	    /* Build a lowercase copy (ASCII only; CJK passes through untouched)
1148	     * so substring checks are case-insensitive for the latin keywords. */
1149	    char buf[LVGL_UI_MSG_MAX_LEN];
1150	    size_t i;
1151	    for (i = 0; i < sizeof(buf) - 1 && text[i]; i++) {
1152	        buf[i] = (text[i] >= 'A' && text[i] <= 'Z') ? (text[i] + 32) : text[i];
1153	    }
1154	    buf[i] = '\0';
1155	
1156	    /* Conclusion: explicit yes/no or recommendation phrasing */
1157	    if (strstr(buf, "yes") || strstr(buf, " no") || strstr(buf, "no.") ||
1158	        strstr(buf, "no,") || strstr(buf, "\xe5\x80\xbc\xe5\xbe\x97") /* 值得 */ ||
1159	        strstr(buf, "\xe4\xb8\x8d\xe5\xbb\xba\xe8\xae\xae") /* 不建议 */ ||
1160	        strstr(buf, "\xe5\xbb\xba\xe8\xae\xae") /* 建议 */ ) {
1161	        return LVGL_UI_CARD_COLOR_CONCLUSION;
1162	    }
1163	
1164	    /* Structured: Gerrit change status keywords (latin) or 状态: */
1165	    if (strstr(buf, "merged") || strstr(buf, "abandoned") ||
1166	        strstr(buf, "status:") || strstr(buf, "\xe7\x8a\xb6\xe6\x80\x81") /* 状态 */ ) {
1167	        return LVGL_UI_CARD_COLOR_STRUCTURED;
1168	    }
1169	
1170	    /* Jira: workflow status or assignee fields */
1171	    if (strstr(buf, "more info") || strstr(buf, "assignee") ||
1172	        strstr(buf, "\xe7\xbb\x8f\xe5\x8a\x9e\xe4\xba\xba") /* 经办人 */ ||
1173	        strstr(buf, "jira") ) {
1174	        return LVGL_UI_CARD_COLOR_JIRA;
1175	    }
1176	
1177	    return LVGL_UI_CARD_COLOR_PLAIN;
1178	}
