299	/* Idle-yield support: when the pet status ring is enabled, the chat screen
300	 * yields the foreground to the pet after PET_IDLE_YIELD_MS of message silence.
301	 * All access is confined to the LVGL thread (init creates the timer; the send
302	 * async cb resets the tick; the timer cb does the yield). */
303	static lv_timer_t *s_pet_idle_timer = NULL;
304	static uint32_t    s_pet_last_msg_tick = 0;
