306	static void pet_idle_timer_cb(lv_timer_t *t)
307	{
308	    (void)t;
309	    if (!s_state.initialized || !s_state.screen_visible) return;
310	    if (!pet_status_view_is_visible() &&
311	        (lv_tick_get() - s_pet_last_msg_tick) >= PET_IDLE_YIELD_MS)
312	      {
313	        /* Yield: the chat screen stays alive but releases the foreground so
314	         * the pet home screen shows.  Clearing screen_visible lets the next
315	         * incoming message re-take the foreground via lvgl_ui_channel_show. */
316	        s_state.screen_visible = false;
317	        pet_status_view_show();
318	        syslog(LOG_INFO, "[%s] idle → pet home screen\n", TAG);
319	      }
320	}
