114	static int32_t align_round_up(int32_t v, uint16_t align)
115	{
116	    return (v + align - 1) & ~(align - 1);
117	}
118	
119	static void rounder_cb(lv_event_t * e)
120	{
121	    lv_nuttx_lcd_t * lcd = lv_event_get_user_data(e);
122	    lv_area_t * area = lv_event_get_param(e);
123	    struct lcddev_area_align_s * align_info = &lcd->align_info;
124	    int32_t w;
125	    int32_t h;
126	
127	    area->x1 &= ~(align_info->col_start_align - 1);
128	    area->y1 &= ~(align_info->row_start_align - 1);
129	
130	    w = align_round_up(lv_area_get_width(area), align_info->width_align);
131	    h = align_round_up(lv_area_get_height(area), align_info->height_align);
132	
133	    area->x2 = area->x1 + w - 1;
134	    area->y2 = area->y1 + h - 1;
135	}
136	
137	static void flush_cb(lv_display_t * disp, const lv_area_t * area_p,
138	                     uint8_t * color_p)
139	{
140	    lv_nuttx_lcd_t * lcd = disp->driver_data;
141	    lv_color_format_t cf = lv_display_get_color_format(disp);
142	
143	    lcd->area.row_start = area_p->y1;
144	    lcd->area.row_end = area_p->y2;
145	    lcd->area.col_start = area_p->x1;
146	    lcd->area.col_end = area_p->x2;
147	    lcd->area.stride = lv_draw_buf_width_to_stride(lcd->area.col_end - lcd->area.col_start + 1, cf);
148	    lcd->area.data = (uint8_t *)color_p + (LV_COLOR_FORMAT_IS_INDEXED(cf) ?
149	                                           LV_COLOR_INDEXED_PALETTE_SIZE(cf) * 4 : 0);
150	    ioctl(lcd->fd, LCDDEVIO_PUTAREA, (unsigned long) & (lcd->area));
151	    lv_display_flush_ready(disp);
152	}
153	
154	static lv_display_t * lcd_init(int fd, int hor_res, int ver_res)
155	{
156	    lv_draw_buf_t * draw_buf = NULL;
157	    lv_draw_buf_t * draw_buf_2 = NULL;
158	    lv_nuttx_lcd_t * lcd = lv_malloc_zeroed(sizeof(lv_nuttx_lcd_t));
159	    LV_ASSERT_MALLOC(lcd);
160	    if(lcd == NULL) {
161	        LV_LOG_ERROR("lv_nuttx_lcd_t malloc failed");
162	        return NULL;
163	    }
164	
165	    lv_display_t * disp = lv_display_create(hor_res, ver_res);
166	    if(disp == NULL) {
167	        lv_free(lcd);
168	        return NULL;
169	    }
170	
171	    lv_color_format_t cf = lv_display_get_color_format(disp);   /* Use default cf */
172	#if LV_NUTTX_LCD_BUFFER_COUNT > 0
173	    lv_display_render_mode_t render_mode = LV_DISPLAY_RENDER_MODE_FULL;
174	#else
175	    lv_display_render_mode_t render_mode = LV_DISPLAY_RENDER_MODE_PARTIAL;
176	#endif
177	
178	    draw_buf = lv_draw_buf_create(hor_res, ver_res, cf, LV_STRIDE_AUTO);
179	    if(draw_buf == NULL) {
180	        LV_LOG_ERROR("display draw_buf create failed");
181	        lv_free(lcd);
182	        return NULL;
183	    }
184	
185	#if LV_NUTTX_LCD_BUFFER_COUNT == 2
186	    draw_buf_2 = lv_draw_buf_create(hor_res, ver_res, cf, LV_STRIDE_AUTO);
187	    if(draw_buf_2 == NULL) {
188	        LV_LOG_ERROR("display draw_buf_2 malloc failed");
189	        lv_free(lcd);
190	        lv_draw_buf_destroy(draw_buf);
191	        return NULL;
192	    }
193	#endif
194	
195	    lcd->fd = fd;
196	    if(ioctl(fd, LCDDEVIO_GETAREAALIGN, &lcd->align_info) < 0) {
197	        perror("Error: ioctl(LCDDEVIO_GETAREAALIGN) failed");
198	    }
199	
200	    lcd->disp = disp;
201	    lv_display_set_draw_buffers(lcd->disp, draw_buf, draw_buf_2);
202	    lv_display_set_render_mode(lcd->disp, render_mode);
203	    lv_display_set_flush_cb(lcd->disp, flush_cb);
204	    lv_display_add_event_cb(lcd->disp, rounder_cb, LV_EVENT_INVALIDATE_AREA, lcd);
205	    lv_display_add_event_cb(lcd->disp, display_release_cb, LV_EVENT_DELETE, lcd->disp);
206	    lv_display_set_driver_data(lcd->disp, lcd);
207	
208	    return lcd->disp;
209	}
