211	static void display_release_cb(lv_event_t * e)
212	{
213	    lv_display_t * disp = (lv_display_t *) lv_event_get_user_data(e);
214	    lv_nuttx_lcd_t * dsc = lv_display_get_driver_data(disp);
215	    if(dsc) {
216	        lv_display_set_driver_data(disp, NULL);
217	        lv_display_set_flush_cb(disp, NULL);
218	
219	        /* clear display buffer */
220	        if(disp->buf_1) {
221	            lv_draw_buf_destroy(disp->buf_1);
222	            disp->buf_1 = NULL;
223	        }
224	        if(disp->buf_2) {
225	            lv_draw_buf_destroy(disp->buf_2);
226	            disp->buf_2 = NULL;
227	        }
228	
229	        /* close device fb */
230	        if(dsc->fd >= 0) {
231	            close(dsc->fd);
232	            dsc->fd = -1;
233	        }
234	        lv_free(dsc);
235	        LV_LOG_USER("Done");
236	    }
237	}
