/* Water-ripple idle shimmer callbacks.  water_opa_cb breathes the pill's
 * opacity like a rippling water surface; water_shadow_cb breathes the glow
 * (shadow) so the ripple reads as a soft light spreading from the pill.  Both
 * run on distinct periods so the shimmer never phase-locks into a simple
 * blink. */
static void water_opa_cb(void* obj, int32_t v)
{
    /* 0..100 → opacity 255..190 (gentle surface undulation, not a hard blink) */
    lv_opa_t opa = LV_OPA_COVER - (v * (LV_OPA_COVER - 190)) / 100;
    lv_obj_set_style_opa((lv_obj_t*)obj, opa, 0);
}

static void water_shadow_cb(void* obj, int32_t v)
{
    /* 0..100 → glow width 8..22px and opacity 30..80, a breathing halo. */
    int32_t w = 8 + (v * 14) / 100;
    lv_opa_t o = LV_OPA_30 + (v * (LV_OPA_80 - LV_OPA_30)) / 100;
    lv_obj_set_style_shadow_width((lv_obj_t*)obj, w, 0);
    lv_obj_set_style_shadow_opa((lv_obj_t*)obj, o, 0);
}

/* Start the idle water-ripple shimmer on the PTT pill.  Idempotent: stops any
 * existing water anim first so repeat calls (e.g. after recording ends) don't
 * stack animators on the same property. */
static void ptt_water_anim_start(void)
{
    if (!s_state.ptt_btn) return;

    lv_anim_del(s_state.ptt_btn, water_opa_cb);
    lv_anim_del(s_state.ptt_btn, water_shadow_cb);

    lv_anim_init(&s_state.water_anim);
    lv_anim_set_var(&s_state.water_anim, s_state.ptt_btn);
