    lv_anim_set_time(&s_state.water_anim, 2200);
    lv_anim_set_repeat_count(&s_state.water_anim, LV_ANIM_REPEAT_INFINITE);
    lv_anim_set_playback_time(&s_state.water_anim, 2200);
    lv_anim_set_exec_cb(&s_state.water_anim, water_opa_cb);
    lv_anim_start(&s_state.water_anim);

    lv_anim_init(&s_state.water_shadow_anim);
    lv_anim_set_var(&s_state.water_shadow_anim, s_state.ptt_btn);
    lv_anim_set_values(&s_state.water_shadow_anim, 0, 100);
    lv_anim_set_time(&s_state.water_shadow_anim, 1600);
    lv_anim_set_repeat_count(&s_state.water_shadow_anim, LV_ANIM_REPEAT_INFINITE);
    lv_anim_set_playback_time(&s_state.water_shadow_anim, 1600);
    lv_anim_set_exec_cb(&s_state.water_shadow_anim, water_shadow_cb);
    lv_anim_start(&s_state.water_shadow_anim);
}

