input.new_string:
/* Animation callback wrapper — lv_obj_set_style_opa requires the
 * selector argument, so we cannot cast it directly as exec_cb. */
static void anim_opa_cb(void* obj, int32_t v)
{
    lv_obj_set_style_opa((lv_obj_t*)obj, (lv_opa_t)v, 0);
}

/* Water-ripple idle shimmer for the "请说" pill.  Two independent animators
 * run on distinct periods so the effect reads as a soft surface undulation
 * rather than a mechanical blink:
 *   water_opa_cb   — opacity breathes 255..190 (the surface dims/brightens)
 *   water_shadow_cb — the orange glow widens/narrows (light spreading outward)
 * Recording swaps the opacity anim for the red rec pulse; the glow keeps
 * rippling throughout. */
static void water_opa_cb(void* obj, int32_t v)
{
    lv_opa_t opa = LV_OPA_COVER - (v * (LV_OPA_COVER - 190)) / 100;
    lv_obj_set_style_opa((lv_obj_t*)obj, opa, 0);
}

static void water_shadow_cb(void* obj, int32_t v)
{
    int32_t w = 8 + (v * 14) / 100;                       /* 8 → 22 px */
    lv_opa_t o = LV_OPA_30 + (v * (LV_OPA_80 - LV_OPA_30)) / 100; /* 30 → 80 */
    lv_obj_set_style_shadow_width((lv_obj_t*)obj, w, 0);
    lv_obj_set_style_shadow_opa((lv_obj_t*)obj, o, 0);
}

/* Idempotent: stop any existing water anim first so repeat calls (e.g. after
 * recording ends) don't stack animators on the same property. */
static void ptt_water_anim_start(void)
{
    if (!s_state.ptt_btn) return;

    lv_anim_del(s_state.ptt_btn, water_opa_cb);
    lv_anim_del(s_state.ptt_btn, water_shadow_cb);

    lv_anim_init(&s_state.water_anim);
    lv_anim_set_var(&s_state.water_anim, s_state.ptt_btn);
    lv_anim_set_values(&s_state.water_anim, 0, 100);
    lv_anim_set_time(&s_state.water_anim, 2200);
    lv_anim_set_repeat_count(&s_state.water_anim, LV_ANIM_REPEAT_INFINITE);
    lv_anim_set_playback_time(&s_state.water_anim, 2200);
    lv_anim_set_exec_cb(&s_state.water_anim, water_opa_cb);
    lv_anim_start(&s_state.water_anim);

    lv_anim_init(&s_state.water_shadow_anim);
    lv_anim_set_var(&s_state.water_shadow_anim, s_state.ptt_btn);
    lv_anim_set_values(&s_state.water_shadow_anim, 0, 100);
    lv_anim_set_time(&s_state.water_shadow_anim, 1600);
    lv_anim_set_repeat_count(&s_state.water_shadow_anim, LV_ANIM_REPEAT_INFINITE);
    lv_anim_set_playback_time(&s_state.water_shadow_anim, 1600);
    lv_anim_set_exec_cb(&s_state.water_shadow_anim, water_shadow_cb);
    lv_anim_start(&s_state.water_shadow_anim);
}

static void ptt_water_anim_stop(void)
{
    if (!s_state.ptt_btn) return;
    lv_anim_del(s_state.ptt_btn, water_opa_cb);
    lv_anim_del(s_state.ptt_btn, water_shadow_cb);
}

static void recording_indicator_start(void)
{
    /* Idle water shimmer yields to the recording pulse (avoids two opacity
     * animators fighting over the pill). */
    ptt_water_anim_stop();

    /* PTT button: red background + slight scale-up */
    lv_obj_set_style_bg_color(s_state.ptt_btn, lv_color_hex(UI_PAL_ERROR), 0);
    lv_obj_set_style_transform_scale(s_state.ptt_btn, 280, 0);

