/* M4 frame-rate probe: measure the LCDDEVIO_PUTAREA ioctl duration (SPI
 * throughput) and periodic flush rate.  Guarded by the first-40 + every-100
 * log pattern so steady-state stays quiet.  Remove after M4 settles. */
static int s_flush_count = 0;
static struct timespec s_rate_t0;

static void flush_cb(lv_display_t * disp, const lv_area_t * area_p,
                     uint8_t * color_p)
{
    lv_nuttx_lcd_t * lcd = disp->driver_data;
    int ret;
    struct timespec t0, t1;
    long us;

    lcd->area.row_start = area_p->y1;
    lcd->area.row_end = area_p->y2;
    lcd->area.col_start = area_p->x1;
    lcd->area.col_end = area_p->x2;
    lcd->area.data = (uint8_t *)color_p;

    clock_gettime(CLOCK_MONOTONIC, &t0);
    ret = ioctl(lcd->fd, LCDDEVIO_PUTAREA, (unsigned long) & (lcd->area));
    clock_gettime(CLOCK_MONOTONIC, &t1);

    us = (t1.tv_sec - t0.tv_sec) * 1000000 + (t1.tv_nsec - t0.tv_nsec) / 1000;

    if (s_flush_count == 0)
      s_rate_t0 = t0;

    if (s_flush_count < 40 || ret < 0)
      {
        int w = area_p->x2 - area_p->x1 + 1;
        int h = area_p->y2 - area_p->y1 + 1;
        /* (w*h*2) bytes / us = bytes per microsecond = MB/s (decimal). */
        syslog(LOG_INFO, "[lv_nuttx_lcd] flush #%d %dx%d rc=%d %ldus"
               " (%ld MB/s)\n", ++s_flush_count, w, h, ret, us,
               us > 0 ? (long)((w * h * 2) / us) : 0);
      }
    else
      {
        s_flush_count++;
      }

    /* Every 100 flushes: report the rolling flush rate. */
    if (s_flush_count >= 100 && (s_flush_count % 100) == 0)
      {
        long ms = (t1.tv_sec - s_rate_t0.tv_sec) * 1000
                + (t1.tv_nsec - s_rate_t0.tv_nsec) / 1000000;
        syslog(LOG_INFO, "[lv_nuttx_lcd] rate: %d flushes in %ldms"
               " (%.1f flush/s)\n", s_flush_count, ms,
               ms > 0 ? (float)s_flush_count * 1000.0f / ms : 0.0f);
        s_rate_t0 = t1;
      }

    lv_display_flush_ready(disp);
}

static lv_display_t * lcd_init(int fd, int hor_res, int ver_res)
{
    lv_color_t * draw_buf = NULL;
    lv_color_t * draw_buf_2 = NULL;
    lv_nuttx_lcd_t * lcd = lv_malloc_zeroed(sizeof(lv_nuttx_lcd_t));

        lv_coord_t rw = lv_display_get_horizontal_resolution(disp);
        lv_coord_t rh = lv_display_get_vertical_resolution(disp);
        if (rw > 0 && rh > 0) {
            disp_w = rw;
            disp_h = rh;
            syslog(LOG_INFO, "[%s] display %ldx%ld\n", TAG,
                   (long)disp_w, (long)disp_h);
        }
    }

    /* Round-face geometry.  The BK7258 JD9853 panel is a round watch face
     * (Ø224) inscribed in a 240×296 rectangle centered at (120,148), leaving
     * 8px side bezels and 36px top/bottom bezels.  The 466 reference is a full
     * square face (Ø466, no bezel).  We derive the inscribed circle from the
     * panel and lay out every widget inside it, so nothing spills into the
     * bezel or off screen on either board. */
    bool round_panel = (disp_w == 240 && disp_h == 296);
    int32_t round_d  = round_panel ? 224 : ((disp_w < disp_h) ? disp_w : disp_h);
    int32_t cx       = disp_w / 2;
    int32_t cy       = disp_h / 2;
    int32_t face_r   = round_d / 2;

    /* Inner gutters as fractions of the circle (≈13/34/9/11px on the real
     * face).  top_m clears the close button sitting in the upper-right arc. */
    int32_t side_m   = (round_d * 6)  / 100;   /* chat_list side gutter */
    int32_t top_m    = (round_d * 15) / 100;   /* chat_list top gutter */
    int32_t bot_m    = (round_d * 4)  / 100;   /* gutter below the PTT pill */
    int32_t ptt_gap  = (round_d * 5)  / 100;   /* gap between list and pill */

    /* "请说" PTT pill: a wide horizontal rounded rectangle at the bottom. */
    int32_t ptt_w    = (round_d * 60) / 100;
    int32_t ptt_h    = (round_d * 18) / 100;

    /* Close button: upper-right inside the circle (center coordinates). */
    int32_t close_cx = cx + (face_r * 55) / 100;    /* ≈182 on the real face */
    int32_t close_cy = cy - (face_r * 82) / 100;    /* ≈56 on the real face */

    /* Create main screen with dark background */
    s_state.screen = lv_obj_create(NULL);
    if (!s_state.screen) {
        syslog(LOG_ERR, "[%s] screen create failed\n", TAG);
        ret = -EIO;
        goto cleanup;
    }

    lv_obj_set_style_bg_color(s_state.screen, lv_color_hex(UI_PAL_BG), 0);
    lv_obj_set_style_bg_opa(s_state.screen, LV_OPA_COVER, 0);
    /* Do NOT call lv_screen_load() here — we load the screen on
     * demand when the user activates the chat UI, to avoid
